    ('DRM385H1', 'Special Topics in Drama, Theatre and Performance Studies', '36L', 'A focused, in-depth examination of specific issues in drama, theatre and performance studies. Special Topics vary for Breadth distribution depending on the course content. Please check Special Topics under Group A on the CDTPS undergraduate web page for more details.', null, null, '{"operator": "OR", "items": ["DRM101Y1", {"credits": 4.0, "department": null}]}'::jsonb),
