    ('DRM390Y1', 'Independent Studies in Drama, Theatre and Performance Studies', null, 'An independent research project at the 300-level, proposed by the student in conversation with a full-time faculty member who agrees to act as their supervisor for the course. Not eligible for CR/NCR option. Restricted to students in the Drama Specialist and Major. An application and a proposal are required in order to enroll in this course. Please consult the CDTPS Independent Study Policy for further details.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM391H1', 'Independent Studies in Drama, Theatre and Performance Studies', null, 'An independent research project at the 300-level, proposed by the student in conversation with a full-time faculty member who agrees to act as their supervisor for the course. Not eligible for CR/NCR option. Restricted to students in the Drama Specialist and Major. An application and a proposal are required in order to enroll in this course. Please consult the CDTPS Independent Study Policy for further details.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('DRM398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('DRM399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('DRM399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('DRM400H1', 'Advanced Performance', '12T/48P', 'Advanced Performance builds on the training sequence of  DRM200Y1 and  DRM300Y1 by developing students'' acting and performance skills in devised monologues and extensive collaborative scene work. The work focuses on the particulars of creating a character and the creative aspects of the actor''s craft. Ensemble work is a priority and full attendance is required. Restricted to students in the Drama Specialist and Major. A letter of interest is required. The Application Deadline is March 10th. See CDTPS Application Guidelines for information on how to apply.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM300Y1"]}'::jsonb),
    ('DRM402H1', 'Advanced Directing', '36T/36P', 'A hands-on exploration of advanced directing for the theatre. The class is centered on student-directed projects, which are publicly presented at the end of term. An application, a proposal, and an interview in April are required to be considered for enrollment in this course. Please consult the CDTPS Application Guidelines for specific procedures and deadlines.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM302H1"]}'::jsonb),
    ('DRM403Y1', 'Mainstage Performance', '72T/144P', 'This course, taught each year by a different visiting professional theatre director, offers upper-level students the opportunity to explore acting in a full-length production. Plays are selected to challenge students in a variety of different ways, exposing them to a full spectrum of theatre and performance genres and possibilities. Restricted to students in the Drama Specialist and Major. An audition is required. The Application Deadline is March 10th. See CDTPS Application Guidelines for information on how to apply.', 'DRS425H5,  DRS426H5', 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM300Y1", {"operator": "OR", "items": ["DRM301H1", "DRM375H1"]}]}'::jsonb),
    ('DRM413H1', 'Advanced Voice and Movement', '12T/48P', 'This course is a skill-developing companion to  DRM400H1 Advanced Performance, and a co-requisite to  DRM403Y1 Mainstage Performance. It exposes students to a wide range of voice and movement techniques and explores a heightened use of physicality, voice and speech. Restricted to students in the Drama Specialist and Major taking  DRM403Y1.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM300Y1", {"operator": "OR", "items": ["DRM301H1", "DRM375H1"]}]}'::jsonb),
    ('DRM420H1', 'Arts and Politics: Bertolt Brecht, Giorgio Strehler, Robert Wilson and Robert Lepage', '36L', 'Bertolt Brecht played a specific role in the paradigm shift of the art which began at the end of the 19th century. He advanced this change by trying to connect art to its social and political functions and structure with the positive acceptance of the industrial revolution and by trying to transform it with the help of the new technological media. Restricted to students in the Drama Specialist or Major.', 'JDC410H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM424H1', 'Projects in Digital Performance', '18P/18S', 'This course introduces students to independent research-creation in the field of contemporary digital performance. Readings and invited guests will expose students to innovative practices in theatres and online platforms, and outline current political and academic debates around liveness, copyright, and social media. Students will pursue research on a contemporary artist who is integrating the performing arts with computational media, and create a performance piece responding to issues raised by their research.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM428H1', 'Advanced Playwriting', '12T/36P', 'A continuation of  DRM328H1, concentrating upon the in-depth knowledge and practice of playwriting with an emphasis on advanced style and technique of writing for the stage. Students develop their own longer work through in-class exercises, one major written assignment, and a final public presentation. Restricted to students in the Drama Specialist and Major or by permission from the Centre. An application and writing samples (due November 10th) are required in order to be considered for enrollment in this course. Please consult the CDTPS Application Guidelines for information on how to apply.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM328H1"]}'::jsonb),
    ('DRM431H1', 'Advanced Dramaturgy', '36L', 'A continuation of  DRM331H1 Dramaturgy, deepening the critical exploration of more specific and/or specialized aspects of dramaturgy, such as digital dramaturgy, new media dramaturgy, intercultural and transcultural dramaturgy.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM331H1"]}'::jsonb),
    ('DRM454H1', 'Advanced Design', '36L/36P', 'An advanced-level exploration of theatrical design skills and techniques, delving deeper into specific areas of specialization and with more opportunity for independent work. Students are expected to participate in Drama Centre productions in senior creative and leadership roles. NB: To enroll in this course, you will need to complete an application by March 10th. See CDTPS Application Guidelines for more information.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM354H1"]}'::jsonb),
    ('DRM455H1', 'Advanced Production', '36L/36P', 'An advanced-level exploration of production skills and techniques, delving deeper into specific areas of specialization and with more opportunity for independent work. Students are expected to participate in Drama Centre productions in senior creative and leadership roles.  NB: To enroll in this course, you will need to complete an application by March 10th. See CDTPS Application Guidelines for more information.', null, 1, '{"operator": "AND", "items": ["DRM220Y1", "DRM355H1"]}'::jsonb),
    ('DRM462H1', 'Black Playwrights: Resistance, Resilience and Transformation', '18L/18S', 'An exploration of dramatic literature by writers from the African Diaspora (Canada, USA, UK and the Caribbean) from 1959 to the present. The course will identify playwrights central to the development of Black theatre, their plays, and performance practices. Emphasis will be placed on dramaturgical analysis, sociohistorical context, the author''s influences, and relevant critical writing, in order to evaluate these works as sites of social resistance, cultural resilience, and aesthetic transformation. Selected authors include: Lorraine Hansberry, Wole Soyinka, August Wilson, Derek Walcott, Debbie Hunter Green, George Elliott Clarke, Tarell Alvin McCraney, Walter Borden, Suzan-Lori Parks, Kwame Kwei-Armah and Ntozake Shange.', 'DRM488H1 (Senior Seminar in Drama, Theatre and Performance Studies: Black Playwrights), offered in Fall 2019', 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM480H1', 'Internships: Performance and Cultural Arts Organizations', '49P/21S', 'In this course students will participate in partnership-based academic internships with performing and cultural arts organizations. With an emphasis on applying academic learning to the community and workplace contexts, students will strengthen their professional skills development and critical reflective practices through their structured engagement with cultural arts organizations across the city. In addition to regular in-class meetings, readings and assignments, students will complete 49 - 55 hours with a cultural arts organization. Please note that internships will not include performance or performance understudy and will be subject to the availability of partner organizations.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM480Y1', 'Internships: Performance and Cultural Arts Organizations', '98P/42S', 'In this course students will participate in partnership-based academic internships with performing and cultural arts organizations. With an emphasis on applying academic learning to the community and workplace contexts, students will strengthen their professional skills development and critical reflective practices through their structured engagement with cultural arts organizations across the city. In addition to regular in-class meetings, readings and assignments, students will complete 98-112 hours with a cultural arts organization. Please note that internships will not include performance or performance understudy and will be subject to the availability of partner organizations.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM485H1', 'Senior Seminar in Drama, Theatre and Performance Studies', '36L', 'An in-depth examination of selected issues in drama, theatre and performance studies at the 400-level. Special Topics vary for breadth distribution depending on the course content and therefore may be counted towards Groups A or B. Please consult the Undergraduate Drama office or check the CDTPS undergraduate web page for more details. Restricted to students in the Drama Specialist or Major.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM485Y1', 'Senior Seminar: Drama, Theatre and Performance Studies Thesis', '72L', 'Research thesis, emphasizing topics and methods used in drama, theatre and performance studies. Students must obtain permission from the instructor by submitting a research project proposal. The project may engage creative practice, but the thesis itself will be a critical, written work engaging the research and dramaturgy involved in the performance or artwork. Not eligible for CR/NCR option. The application deadline is March 10th. See CDTPS Application Guidelines for information on how to apply. Restricted to students in the Drama Specialist or Major.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM486H1', 'Senior Seminar in Drama, Theatre and Performance Studies', '36P', 'An in-depth examination of selected issues in drama, theatre and performance studies at the 400-level. Special Topics vary for breadth distribution depending on the course content and therefore may be counted towards Groups A or B. Please consult the Undergraduate Drama office or check the CDTPS undergraduate web page for more details. Restricted to students in the Drama Specialist or Major.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM487H1', 'Senior Seminar in Drama, Theatre and Performance Studies', '36L', 'An in-depth examination of selected issues in drama, theatre and performance studies at the 400-level. Special Topics vary for breadth distribution depending on the course content and therefore may be counted towards Groups A or B. Please consult the Undergraduate Drama office or check the CDTPS undergraduate web page for more details. Restricted to students in the Drama Specialist or Major.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM488H1', 'Senior Seminar in Drama, Theatre and Performance Studies', '36L', 'An in-depth examination of selected issues in drama, theatre and performance studies at the 400-level. Special Topics vary for breadth distribution depending on the course content and therefore may be counted towards Groups A or B. Please consult the Undergraduate Drama office or check the CDTPS undergraduate web page for more details. Restricted to students in the Drama Specialist or Major.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM490Y1', 'Independent Studies in Drama, Theatre and Performance Studies', null, 'An independent research project at the 400-level, proposed by the student in conversation with a full-time faculty member who agrees to act as their supervisor for the course. Not eligible for CR/NCR option. Restricted to students in the Drama Specialist and Major. An application and a proposal are required in order to enroll in this course. Please consult the CDTPS Independent Study Policy for further details.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DRM491H1', 'Independent Studies in Drama, Theatre and Performance Studies', null, 'An independent research project at the 400-level, proposed by the student in conversation with a full-time faculty member who agrees to act as their supervisor for the course. Not eligible for CR/NCR option. Restricted to students in the Drama Specialist and Major. An application and a proposal are required in order to enroll in this course.Please consult the CDTPS Independent Study Policy for further details.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "DRM220Y1"]}'::jsonb),
    ('DTS199H1', 'Superman and Other Migrants', '24S', 'From the 1938 debut of Superman until the spate of recent autobiographical graphic novels by immigrants and children of immigrants, the development of the comic and graphic novel form has been intricately bound up with the diaspora experience. In this course, we will explore the emergence of the superhero from the immigrant experience; trace the depiction of migrants, immigrants and refugees in recent graphic novels; and study visual strategies for representing migration and displacement. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('DTS200H1', 'Introduction to Diaspora and Transnational Studies', '24L', 'What is the relationship between place and belonging, between territory and memory? How have the experiences of migration and dislocation challenged the modern assumption that the nation-state should be the limit of identification? What effect has the emergence of new media of communication had upon the coherence of cultural and political boundaries? All of these questions and many more form part of the subject matter of Diaspora and Transnational Studies. This introductory course ex-amines the historical and contemporary movements of peoples and the complex issues of identity and experience to which these processes give rise as well as the creative possibilities that flow from movement and being moved. The area of study is comparative and interdisciplinary, drawing from the social sciences, history, the arts and humanities. Accordingly, this course provides the background to the subject area from diverse perspectives and introduces students to a range of key debates in the field, with particular attention to questions of history, globalization, cultural production and the creative imagination.', 'DTS200Y1,  DTS201H5 and  DTS202H5', 3, null::jsonb),
    ('DTS300H1', 'Qualitative and Quantitative Reasoning', '24L', 'Focuses on research design and training in methods from history, geography, anthropology, literary and cultural studies, and other disciplines appropriate to Diaspora and Transnational Studies. Prepares students to undertake primary research required in senior seminars.', null, 5, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('DTS305H1', 'Special Topics in Diaspora and Transnational Studies', '24L', 'An upper level course. Topics of study vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('DTS310H1', 'Transnational Toronto', '24L', 'Toronto is a city increasingly configured through transnational connections and practices. It is a city defined by the scale at which its residents live their lives; a scale that is no longer (if it ever was) parochial, but extends across time and space to connect people and practice across a multitude of locales. Contemporary understandings of Toronto can only be reached through adopting a transnational lens. This course will examine the processes that have produced Toronto as a transnational city over time, including the dynamics of immigration and mobility, experiences of alienation, the global extension of capitalism, and the (re)formation of communities grounded in the complex dynamics of identities produced in a space that is both ''home'' and away''. We will also explore the specific practices, and connections that produce "Toronto" as a space that transcends its physical geographic boundaries and is continually reproduced in and through the flows of people, capital, objects, ideas, - and the many forces that reproduce and reconfigure these flows.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('DTS311H1', 'Fun in Diaspora', '24L', 'From parkour to "Baby Shark" remixes, concepts and practices surrounding fun, entertainment, and pleasure transcend cultural boundaries, reveal the reach of globalization, and help facilitate the maintenance of transnational communities through shared activities. This course will examine these relationships with fun, and we will also assess cases where concepts of fun diverge and clash in intercultural contexts. Additionally, the class will consider the relationship between entertainment practices and politics, marketing, and social movements. Cases examined will include K-pop fandom, bucket challenges, social media memes, and global YouTube phenomena.', null, 1, null::jsonb),
    ('DTS312H1', 'Exile', '24S', 'Historically used to describe both voluntary departure and enforced banishment from a city, today, "Exile" is perhaps most famously associated with both the Jewish and the Palestinian condition. But exile is also a state of being, one that is creative, critical, and full of meaning-making. This class posits “Exile” as a conceptual framework through which to think through the 21st-century condition of migration and diaspora. Through foundational texts and historic case studies, particularly drawn from East Africa, South Asia, and the Middle East, we will consider how exile has been deployed in order to bring together diverse situations under a unifying theory of both individual and collective experience.', null, 3, null::jsonb),
    ('DTS314H1', 'Citizenship and Multiculturalism', '24S', 'This course examines approaches to belonging and distinction that accompany different models of citizenship. What are some historical and recent trends in the intersections of place, custom, and rights? How have governments related social diversity to social justice in theory and in practice? Areas of emphasis will vary, but may include topics such as authenticity and assimilation; ethno-nationalism; immigration and naturalization policy; indigeneity; insurgency; legacies of colonialism; mass media and popular culture; policing and surveillance; racial stratification; transnational markets; and xenophobia.', null, 3, null::jsonb),
    ('DTS315H1', 'Marriage and Family across Nations, Diasporas, and Boundaries', '12L/12S', 'How do migration and resettlement affect marriage and family life? This course will explore marital, familial, sexual, and other relational aspects of diaspora and migration, examining how marriage and family become tools for maintaining cultural traditions and gender hierarchies but are also areas of life where negotiation, creativity, and rebellion occur. Transnational in its scope, the course will investigate how marriage and family involve choices but also constraints imposed by communities, cultures, religions, and nation-states. A primary objective of this course will be to interrogate how marriage and family relations consist of choices and constraints that are experienced, celebrated, lamented, and resisted. The class will draw on interdisciplinary approaches and present case studies from a variety of diasporic communities in Canada and other migration contexts.', null, 3, null::jsonb),
    ('DTS316H1', 'Filth: Dirt and Dehumanization in Transnational Perspective', '12L/12S', 'This class will draw on research from anthropology, religious studies, environmental studies, and other fields to examine transnational, cross-cultural, and diasporic perspectives on filth and dirt and how these concepts are deployed to create and reinforce social hierarchies in a multitude of global contexts. Discussions will address such topics as colonial encounters and otherization through ideas of cleanliness; the weaponization of filth in transnational practices of violence; the commercialization and exportation of trash from wealthy nations to the global south; migrants, cleaning/cleanliness, and dehumanization; and impurity, gender, and sexuality in diaspora communities.', null, 3, null::jsonb),
    ('DTS390H1', 'Independent Study', null, 'A scholarly project chosen by the student, approved by the Department, and supervised by one of its instructors. Consult with the Diaspora and Transnational Studies Program Office for more information. Not eligible for CR/NCR option.', null, null, '{"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}'::jsonb),
    ('DTS390Y1', 'Independent Study', null, 'A scholarly project chosen by the student, approved by the Department, and supervised by one of its instructors. Consult with the Diaspora and Transnational Studies Program Office for more information. Not eligible for CR/NCR option.', null, null, '{"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}'::jsonb),
    ('DTS401H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS402H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS403H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS404H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200Y1", "CJS200H1", "CJS201H1"]}]}'::jsonb),
    ('DTS405H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS406H1', 'Advanced Topics in Diaspora and Transnationalism', '24S', 'An in-depth investigation of topics in Diaspora and Transnationalism. Content in any given year depends on instructor. Refer to the Centre for Diaspora and Transnational Studies website (https://www.cdts.utoronto.ca/undergraduate/undergraduate-program/current-undergraduate-courses) for more information.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS410H1', 'Diasporic Foodways', '24S', 'Food links people across space and time. As it spirals outward from parochial sites of origin to articulate with new sites, actors and scales, it assumes new substance and meaning in new locales. This movement of food gives rise to new ''foodways'' to help us to understand the past in terms of temporally connected sites of intense interaction. Food also plays a strong role in shaping translocal identities. As peoples have moved in the world, food has played a central role in (re)defining who they are, reproducing myth and ritual, and bounding diasporic communities. This course seeks to address questions surrounding the dynamics of the food ''we'' eat, the ways in which ''we'' eat, the meaning ''we'' give to eating, and the effect of eating in a transnational world. Recognizing that culinary culture is central to diasporic identifications, the focus is on the place of food in the enduring habits, rituals, and everyday practices that are collectively used to produce and sustain a shared sense of diasporic cultural identity.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS411H1', 'Transnational Justice', '24S', 'This course explores the intersection between local conceptions of justice and their transnational and institutional circulations. It interrogates competing meanings of justice and examines the varied practices of actors engaged in justice making domains. From international human rights, to transitional justice and truth and reconciliation, to international legal and traditional justice formulations, the course offers students an opportunity to learn about and critically reflect on the processes and purposes through which justice conceptions are structured, implemented and being contested in the contemporary period. Topics include: theories of transnationalism, transnational justice, social injustice, law and culture, universalism, racism and social inequality.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS412H1', 'The Diasporic Imagination', '24S', 'This course focuses on echoes of diasporic and transnational life in artistic work, and on the significance of aesthetic production to the formation of diasporic and transnational worlds. How have practices, producers, and works of art illuminated the particularities of diasporic life? How do conventions of genre, performance, and tradition shape experiences of borders and crossings? Areas of emphasis will vary but may spotlight particular historical and geographic contexts, and may foreground one or more form, including film, poetry, fiction, music, and dance.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS413H1', 'Global Sexualities', '24S', 'Sexuality is a complex interplay of desires, attractions, interests, and modes of behavior and has diverse meanings in different societies and cultures. In this course, we will examine the notion of sexuality as well as gender identity and expression from an interdisciplinary perspective that is rooted in ethnography. A cross-cultural study of sexuality and gender identity within global and transnational contexts will provide students with an understanding of how the intersections of culture, community, as well as social and political factors affect individuals'' sexual choices and understandings of gender. A particular focus in this course will be experiences of sexuality and gender within diasporic communities.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1", "SDS380H1"]}]}'::jsonb),
    ('DTS414H1', 'Money on the Move', '24S', 'In the eighteenth and nineteenth centuries, industry and finance matured together, pushing people into motion around the world. The instruments of long-distance trade, like insurance, credit and debt, connected cities and continents in new and sometimes unsettling ways. The free movement of goods and cash was mirrored by restrictions on migration to some parts of the world and by forced or coerced migration to others. This course explores the history of the rise of global capitalism at a human scale, exploring how financialization, industrialization and imperialism overlapped and intertwined, and how the remaking of the world in the image of capital weighed on human lives.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS415H1', 'Diaspora at Home', '24S', 'What is the relationship between diaspora and domesticity? What does it mean to inhabit the position of the stranger not in the public life of the city, but in the private sphere of the household? This course approaches questions of migration, labour, and foreignness through the prism of the home. We consider the international phenomenon of migrant domestic labour and how it shapes social and family relations, both in countries of origin such as the Philippines and Ethiopia, as well as in countries of employment such as Canada and Lebanon. But we also reflect on how migration radically transforms life inside the home, affecting what it means to be a parent, a child, or a partner. In doing so we draw upon diverse representations of "the family", kinship, and intimacy across both the humanities and the social sciences.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS416H1', 'Wars, Diaspora and Music', '24S', 'The course explores how composers, performers, songwriters and audiences made sense of traumatic and violent events that they experienced, such as ethnic conflicts, wars, exile and displacement, through music. We will also look at how government ideologies employ music during wars. The case studies will include stories of Jewish, Palestinian, Afghan, Romani, Korean, Rwandan and other diasporas severely affected by wars and violence.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS417H1', '9 to 5: A Transnational History of the Working Day', '24S', 'Work is a central preoccupation in human life and culture, and the working day – measured in daylight, in shifts, or in tasks and ‘gigs’ – is, for most people, the basic unit of work. A ‘day’s work’ is so ubiquitous that it seems natural – but it is not – the offices, worksites, hourly wages and everyday forms of discipline and surveillance that shape working lives have a history. This course explores the transnational and diasporic histories of working life, from plantations to factories to offices to informal work at the margins of global industrial capitalism.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS418H1', 'Violence and Memory: Transnational Approaches', '12L/12S', 'Nation-states not only perpetrate mass violence regularly but also pivotally shape how that violence is remembered and memorialized. In doing this, they shape how communities heal or do not heal from violence. Memorializing violence is also tied to how states both make violence endemic and draw upon violence that may already be endemic within particular social contexts. This class will examine these phenomena in transnational and transhistorical perspective, focusing on case studies spanning different historical eras and various continents. These comparisons will reveal differences and linkages between the formation, utilization, and weaponization of memory in widely divergent contexts.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('DTS419H1', 'History and Counterstories in the Black Mediterranean', '12L/12S', 'This course explores colonial histories and counter- stories of resistance in the Black Mediterranean. Intended not only as a physical space but also as a symbolic site, the Black Mediterranean can be seen as a new theoretical approach useful to understand the racialized production of bodies and borders, and to highlight forms of resistance. The course will focus on Italy and its (post)colonial ties with Libya, Eritrea, Ethiopia and Somalia. Going from the Italian invasion of Eritrea in 1890 to the current so-called "refugee crisis"; the case of Italy illustrates the intersections and resignification of race, bodies and borders in the Mediterranean region, as well as the presence of important histories of resistance and alternative conceptualisations of belonging.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["DTS200H1", "DTS200Y1"]}]}'::jsonb),
    ('EAS100Y1', 'Modern Standard Chinese I', '48L/72T', 'Intended for students with no background in Mandarin or any Chinese dialect, this course provides an introduction to modern standard Chinese as a foreign/second language. The course consists of mandatory lectures and tutorials. Students study a minimum of 450 Chinese characters. Students must go through screening process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'EAS101Y1,  LGGA60H3,  LGGA61H3,  LGGB60H3,  LGGB61H3,  CHI101H5', 1, null::jsonb),
    ('EAS101Y1', 'Modern Chinese I for Students with Prior Background', '48L/48T', 'This course is designed for students who understand elementary Mandarin or any Chinese dialect. The course consists of mandatory lectures and tutorials. Students will learn 600 characters. Students must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'EAS100Y1,  EAS200Y1,  LGGA60H3,  LGGA61H3,  LGGA64H3,  LGGA65H3,  LGGB60H3,  LGGB61H3,  CHI101H5,  CHI103H5,  CHI104H5,  CHI203H5,  CHI204H5', 1, null::jsonb),
    ('EAS103H1', 'Premodern East Asia', '24L/12T', 'Examines how various histories of East Asia can be written by focusing on specific themes in the histories of China, Japan, and Korea to roughly 1600. Required of EAS specialists, majors, and minors.', 'EAS102Y1', 3, null::jsonb),
    ('EAS105H1', 'Modern East Asia', '24L/12T', 'Examines how various histories of East Asia can be written by focusing on specific themes in the histories of China, Japan, and Korea from roughly 1600 to the Cold War. Required of EAS specialists, majors, and minors.', 'EAS102Y1', 3, '{"operator": "AND", "items": ["EAS103H1"]}'::jsonb),
    ('EAS110Y1', 'Modern Standard Korean I', '48L/72T', 'This course is designed to help students build communication skills in the Korean language. Through an integration of listening, speaking, reading and writing, it aims to provide a solid foundation in beginning-level Korean. This course assumes that students do not have any prior knowledge of Korean. Students must go through screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/korean for details.', 'EAS211Y1', 1, null::jsonb),
    ('EAS120Y1', 'Modern Standard Japanese I', '48L/48T', 'This course is for students with no or a very limited background in Japanese. Students must go through screening process conducted by the Department. See www.eas.utoronto.ca/languages/japanese/ for details. Not eligible for CR/NCR option.', 'EAS121H1,  EAS122Y0,  LGGA80H3,  LGGA81H3', 1, null::jsonb),
    ('EAS151H1', 'Modern Standard Japanese I-a', '24L/24T', 'This course is for students with no or a very limited background in Japanese. Not eligible for CR/NCR option.', 'EAS120Y1,  EAS121H1,  EAS122Y0,  LGGA80H3,  LGGA81H3,  LGGA82Y3', 1, null::jsonb),
    ('EAS152H1', 'Modern Standard Japanese I-b', '24L/24T', 'This course, which is a continuation of  EAS151H1, is for students with some background in the Japanese language. All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details. Not eligible for CR/NCR option.', 'EAS120Y1,  EAS222Y0,  LGGA81H3', 1, '{"operator": "AND", "items": ["EAS151H1"]}'::jsonb),
    ('EAS192H1', 'China from the Margins', '24L', 'This course explores how China might be understood through marginal voices, genres, and perspectives. Course focus may include indigeneity, cross-cultural exchange, language policy, and aesthetics, among other themes, across a wide range of media and time periods. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS193H1', 'What is “The Yellow Peril”?', '24L', 'This course explores the old and new reincarnations of “the Yellow Peril” complex. The 2020 naming of COVID-19 as “the Chinese virus” by the U.S. president Donald Trump has provoked much anger, criticism, and concerns for anti-Asian violence and the reagitation of “The Yellow Peril” panic. Yet the imaginaries of “the Yellow Peril” and their power effects have been engrained in our political modernity, the Enlightenment ideas, and its institutions in a much more complex, far-reaching, and intersecting ways in East Asia and beyond. The course will explore various types of cultural productions, including history, literature, film, news media, etc., to introduce the racial, colonial, capitalist, sexual, militarized, and other dimensions of the "Yellow Peril." Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('EAS194H1', 'East Asia through Music', '24L', 'This course will discuss ''East Asia'' through music as composed, performed, recorded, processed, remembered, imagined, and represented. Questions to be asked include: what kinds of sound are recognized as music in East Asia? What are the goals and effects of music? When, where, and how is music performed in East Asia? How is music described in East Asian literature and visual art? How does music translate East Asian literature and visual art? How are certain musical elements—tonality, rhythm, genre, instruments—recognized as ''East Asian''? How is East Asia imagined musically? How are East Asian composers and performers received globally? Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS195H1', 'Shan Shui Landscape: A Cultural Historical Study', '24L', 'This course looks into the history of cultural production of Chinese Shan Shui (lit., mountain and water) landscape representations from an environmental humanities perspective. As an artistic motif, Shan Shui travels between past and present and across various mediums as well as literary and artistic genres. What exactly are we invited to see and contemplate on in the Shan Shui? Are Shan Shui works about "nature," spirit, Qi, or the human world? The course seeks to inquire into these and other questions through examining the concepts, arts, and transformations of selected Shan Shui works in imperial and contemporary China. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS196H1', 'Consumption, Taste and Culture in East Asia', '24S', 'This course explores the roles that consumption and taste play in personal and public lives in East Asia. Course focus may include the cultural histories of food, fashion, tourism, sports, or forms of audio and visual media. (No prior knowledge of East Asian languages or cultures is necessary.) Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS197H1', 'Media Worlds and East Asia', '24S', 'The term "world-making" is often used nowadays to refer to transmedia storytelling, or the creation of story-worlds across serial narratives in a range of entertainment media, such as novels, games, film series/franchises, television shows, comics, and webtoons. This course looks at the ways that media producers and fans, alike, engage with media worlds. More importantly, the course situates these media worlds within a broader conception of "world-making," namely, the geopolitical and economic configuration of modern East Asia. (No prior knowledge of East Asian languages or cultures is necessary.) Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS198H1', 'Martial Arts in East Asian Narratives', '24S', 'What can we learn about East Asian history and culture through its rich tradition of narratives featuring the martial arts? This course introduces short stories and novels dealing with combat and warfare from nearly two thousand years of East Asian literature, exploring issues such as self and society, gender, power, the body, and identity. All texts will be provided in translation, and no prior knowledge of any East Asian language or culture is necessary. The texts explored will vary year to year, depending on the instructor. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS199H1', 'Thinking through Art in Chinese Culture', '24S', 'This seminar explores different visions and methods of art (textual and visual) as a way of thinking about living, knowing, and willing in Chinese culture. Examination of various theoretical texts on arts and literature, as well as works of art themselves, will provide students with knowledge and research skills on arts in Chinese culture, and an expanded sense of Chinese intellectual history. Questions explored in the course will include: How should we understand the concept of Chinese art beyond representation? How did Chinese literati pursue a sense of beauty through their poetry and painting? How is beauty apprehended in natural and constructed landscapes? What are the political and social functions of art education in Chinese culture? How do Chinese artists fit into a global cultural context? (No prior knowledge of East Asian languages or cultures is necessary.) Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('EAS200Y1', 'Modern Standard Chinese II', '96L', 'This course is a continuation of  EAS100Y1. Students learn major grammatical structures which are not introduced in the first year and expand their vocabulary. Students who do not meet the prerequisite must go through a placement process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'EAS101Y1,  EAS201H1,  LGGB60H3,  LGGB61H3,  LGGB62H3,  LGGB63H3,  CHI203H5,  CHI204H5', 1, '{"operator": "AND", "items": ["EAS100Y1"]}'::jsonb),
    ('EAS201H1', 'Modern Chinese II for Students with Prior Background', '48L', 'This course is a continuation of  EAS101Y1. It focuses on development of students'' listening, speaking, reading, and writing skills at an intermediate low level. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'EAS200Y1,  LGGB60H3,  LGGB61H3,  LGGB62H3,  LGGB63H3,  CHI203H5,  CHI204H5', 1, '{"operator": "AND", "items": ["EAS101Y1"]}'::jsonb),
    ('EAS209H1', 'Approaches to East Asia', '24L/12T', 'Required of EAS specialists and majors, this course introduces various approaches, theories, and methodologies for the study of East Asian societies and cultures. As the course serves as a foundation for upper-level EAS courses, it should be taken as early as possible, preferably in the second year.', 'EAS209Y1', null, '{"operator": "AND", "items": ["EAS103H1", "EAS105H1"]}'::jsonb),
    ('EAS210Y1', 'Modern Standard Korean II', '48L/72T', 'As a continuation of  EAS110Y1, this course is designed to help students improve their skills in the Korean language. Students in this course are expected to perform basic communicative functions, read and write paragraph-level texts, and conjugate verbs/adjectives accurately. Students who do not meet the prerequisite must go through placement process conducted by the Department. See https://www.eas.utoronto.ca/languages/korean for details.', 'EAS211Y1,  EAS212H1', 1, '{"operator": "AND", "items": ["EAS110Y1"]}'::jsonb),
    ('EAS211Y1', 'Accelerated Modern Standard Korean I & II', '96L', 'Covering both  EAS110Y1 and  EAS210Y1, the course is ideal for self-motivated students who enjoy fast-paced language learning, students with a passion for Korean films and television, students with some listening and speaking skills from prior study or family background, and students taking the full four-year course series. Successful completion of the course fulfils the prerequisite for  EAS310Y1. Students must go through screening process conducted by the Department. See www.eas.utoronto.ca/languages/korean for details.', 'EAS110Y1,  EAS210Y1,  EAS212H1', 1, null::jsonb),
    ('EAS212H1', 'Accelerated Modern Standard Korean II', '48L', 'As a continuation of  EAS110Y1, this course is designed to help students increase their Korean communication skills at beginner high to intermediate low levels. It is ideal for self-motivated students who enjoy fast-paced language learning, and students who have built basic language skills from prior study. Successful completion of the course fulfils the prerequisite for  EAS310Y1. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/korean for details.', 'EAS210Y1, EAS211Y1', 1, '{"operator": "AND", "items": ["EAS110Y1"]}'::jsonb),
    ('EAS213H1', 'Korean Language in Media and Pop-Culture', '48L', 'This course aims to enhance Korean language proficiency through immersive engagement with contemporary media, including news, K-pop, webtoons, and social media. It focuses on improving learners'' intercultural and pragmatic understanding by exploring real-world language use across various platforms. The lecture will be delivered using a mix of Korean and English.', null, 1, '{"operator": "OR", "items": ["EAS110Y1", "EAS211Y1", "LGGA12H3"]}'::jsonb),
    ('EAS215H1', 'Korean Language on Screen', '48L', 'This course sharpens Korean language skills through the captivating world of K-dramas and films. Students engage with authentic dialogues and cultural nuances, enhancing vocabulary, idiomatic expressions, and cultural awareness. By analyzing language use in visual media, students will develop intercultural and pragmatic competence. Instruction is in both Korean and English.', null, 1, '{"operator": "OR", "items": ["EAS110Y1", "EAS211Y1", "LGGA12H3"]}'::jsonb),
    ('EAS218H1', 'Classical Chinese Prose', '24L', 'This course introduces the form and types of prose in classical Chinese literature by critical reading of some basic Chinese texts and their English translations on various themes, such as history, philosophy, religion and art.', null, 1, null::jsonb),
    ('EAS219H1', 'Cultural History of Food & Drink in East Asia', '24L', 'This course introduces historical, literary, and anthropological issues related to the consumption of food and/or drink in East Asia. Through a wide variety of reading materials, it focuses on the relationships between food/drink consumption and commerce, religion, social regulation, medicine, and cultural identity, among others.', null, 1, null::jsonb),
    ('EAS220Y1', 'Modern Standard Japanese II', '48L/48T', 'This is an advanced beginner level language course for those who completed  EAS120Y1 or  EAS121H1 with a minimum grade of 67%. Students who do not meet the prerequisite must go through placement process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS223Y0', 1, '{"operator": "OR", "items": ["EAS120Y1", "EAS121H1"]}'::jsonb),
    ('EAS231H1', 'Tales of the Supernatural in Chinese Literature', '24L', 'This course explores the long tradition of writing about the fantastic, strange, and supernatural in Chinese literature, from the earliest records to medieval tales, late imperial opera, and contemporary science fiction. In addition to close reading and interpretation, we will situate these texts in their social and cultural contexts, examining critical moments of transformation in Chinese history and the enduring questions they raise in terms of philosophy, religion, gender, ethnicity, and politics.', null, 1, null::jsonb),
    ('EAS235H1', 'Perceptions of China in Japanese Literature', '24L', 'Lectures on Japanese literary negotiations with China, the Chinese and Chineseness, ranging from celebration of shared cultural practices and aestheticization of China to nativist resistance to Chinese cultural hegemony. Required readings are available in English translation, including Tale of Genji, Tale of Middle-Councillor Hamamatsu (medieval romance), Haku Rakuten (No Play), Battles of Coxinga (Kabuki play), Three-Cornered World (by Soseki), and Wild Goose (by Ogai).', null, 1, null::jsonb),
    ('EAS236H1', 'Queer Feminist Literature: Writing in Global Capitalism', '24L', 'This course is an introduction to gender and sexuality studies and East Asian queer feminist writings produced in the context of global capitalism.', null, 1, null::jsonb),
    ('EAS241H1', 'Introduction to Chinese Philosophy', '36L', 'A historical introduction to Chinese philosophy, covering selected figures and texts from the Warring States period through the Qīng dynasty. Schools of thought covered include Confucianism, Mohism, Daoism, Legalism, "Profound Learning," Neo-Confucianism, and "Evidential Learning." Texts and thinkers include the Confucian Analects, Mòzǐ, Mèngzǐ, Xúnzǐ, Dàodéjīng, Zhuāngzǐ, Hán Fēi, Guō Xiàng, Zhū Xī, Wáng Yángmíng, and Dài Zhèn.', 'PHL237H1', 2, null::jsonb),
    ('EAS242H1', 'Japanese Cinemas I: Film Form and the Problems of Modernity', '36L/12T', 'This course investigates how film aesthetics relate to the most profound socio-historical problems of Japanese modernity. It also considers the ways various filmmakers employ cinematic form to engage the social problems of their moment. Part I focuses on the 1890s - 1950s.', 'EAS237Y1', 1, null::jsonb),
    ('EAS243H1', 'Japanese Cinemas II: Film Form and the Problems of Modernity', '36L/12T', 'This course investigates how film aesthetics relate to the most profound socio-historical problems of Japanese modernity. It also considers how various film makers employ cinematic form to engage the social problems of their moment. Part II focuses on the 1960s - present.', 'EAS237Y1', 1, null::jsonb),
    ('EAS245H1', 'Premodern Japanese History', '24L', 'A survey of the history of premodern Japan from earliest recorded histories to the establishment of the Tokugawa regime in the seventeenth century. Uses a wide range of translated primary Japanese texts to illuminate the emergence of cultural forms and their conjunction with social, economic, religious, and political trends.', null, 3, null::jsonb),
    ('EAS246H1', 'Early Modern Japanese History', '24L', 'A survey of the history of Japan from about 1600 until the disintegration of the Tokugawa regime in the mid-19th century. Uses a wide range of translated primary Japanese texts to illuminate the emergence of cultural forms and their conjunction with social, economic, religious, and political trends.', null, 3, null::jsonb),
    ('EAS247H1', 'History of Capitalism in Modern Japan', '24L', 'This course provides a historical narrative of the development of the capitalist mode of production in Japan, from the mid-19th century to the present day. Readings include texts from various disciplines: economics, philosophy, social and labour history, and literature.', null, 3, null::jsonb),
    ('EAS248H1', 'Marxism and East Asia', '24L', 'This course focuses on how Marxism became one of the most important and influential systems of revolutionary thought in East Asian countries such as Japan, Korea, and China in the twentieth century, with enormous repercussions for our present historical conjuncture. The course particularly focuses on the theoretical creativity and impasses that went into translating the basic tenets of Marxism to address particular, national questions in East Asia.', null, 3, null::jsonb),
    ('EAS249H1', 'Sinophone Cinemas: Revolution of the Sensible World', '24L/24P', 'This course is an introduction to the cinematic avant-garde movements that follow the end of the first Cold War across the Sinophone world, specifically China, Hong Kong, and Taiwan. Taking up the legacies of the Cold War, we examine specific film histories in each region and situate the New Wave movements of the past four decades in a vast terrain that is shaped by the narratives of war, nationalism, colonialism, economic integration, urbanization, among others.', null, 1, null::jsonb),
    ('EAS251H1', 'Aesthetics and Politics in 20th Century Korea', '24L', 'This lecture course examines key questions and texts in the history of literature from the Korean peninsula during the twentieth century, exploring how aesthetic form refracted the experiences of colonialism, division, and the formation of opposing nation-states.', null, 1, null::jsonb),
    ('EAS252H1', 'Modern Standard Japanese II-a', '24L/24T', 'This course is an advanced beginners'' level Japanese language course, which is designed for those who have completed  EAS152H1 or  EAS120Y1 or  EAS121H1 with a minimum grade of 67%. All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS220Y1,  EAS223Y0', 1, '{"operator": "OR", "items": ["EAS152H1", "EAS120Y1", "EAS121H1"]}'::jsonb),
    ('EAS253H1', 'Modern Standard Japanese II-b', '24L/24T', 'This course, which is a continuation of  EAS252H1, is for students who have a good foundation of lower beginners'' grammar, vocabulary and kanji knowledge and have not yet acquired the proficiency required to take  EAS350Y1 (previously  EAS320Y1). All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS220Y1,  EAS221H1,  EAS223Y0', 1, '{"operator": "AND", "items": ["EAS252H1"]}'::jsonb),
    ('EAS256H1', 'Chinese Literature (Pre-Qin to Tang)', '24L', 'A survey of major works in premodern Chinese literature, including poetry, essays, and short narratives from the pre-Qin through Tang eras (11th century BCE - 10th century CE).', 'EAS336Y1, EAS336H1', 1, null::jsonb),
    ('EAS257H1', 'Chinese Literature (Song to Qing)', '24L', 'A survey of major works in premodern Chinese literature, including poetry, essays, short narratives and drama from the Song through Qing dynasties (10th - 19th centuries CE).', 'EAS337Y1, EAS337H1', 1, null::jsonb),
    ('EAS263H1', 'Classical Japanese Literature', '24L', 'This course examines canonical literary works written in classical and sinitic Japanese (bungo and kanbun), including poetry, narrative, and theatre, produced from the Nara Period to the Edo Period (roughly 8th to 19th Centuries), with an emphasis on rhetoric, media, performance, reception history, canon formation and gender relations. Themes include: orality and literacy; masculine and feminine discourses; image and text; poetry and narrative; (auto)biography and fiction; intertextuality and authorship; the supernatural and realistic; establishment and resistance; and the centre and periphery. All readings will be in English.', null, 1, null::jsonb),
    ('EAS270H1', 'Narratives of 19th-Century Korea', '24L', 'This course examines the tumultuous events of 19th-century Korea – from peasant uprisings to gunboat diplomacy and from the decline of slavery to the economy''s integration into global capitalism – together with the ways these events have been subjected to the changing and contentious interpretations of historians.', null, 3, null::jsonb),
    ('EAS271H1', '20th Century Korean Colonial History', '24L', 'An exploration of Korean colonial history in a comparative and global context, including coverage of controversies over political economy, gender, race, architecture, and later public memory debates.', 'EAS271Y1', 3, null::jsonb),
    ('EAS272H1', 'The Two Koreas in World History', '24L', 'This course begins with the division of the peninsula into two mutually-hostile Koreas in the context of decolonization and the Cold War, and traces the struggles of peoples on both sides of the divide down to the late 20th century.', null, 3, null::jsonb),
    ('EAS273H1', 'Modern Chinese Cities', '24L', 'This course offers a critical review of the history and historiography of modern Chinese cities. Focusing on the development of specific Chinese cities, the course emphasizes understanding the socio-cultural production of space as well as analytical reading of landscape, urban imagery, and urban writings.', null, 1, null::jsonb),
    ('EAS274H1', 'Popular Culture in East Asia', '24L', 'Through various forms of popular culture in the 20th century, this course explores the cultural contexts and social trajectories of China, Japan and Korea. Forms of popular culture studied include art, visual culture, consumer habits, foodways, advertising, music, and fashion.', null, 1, null::jsonb),
    ('EAS278H1', 'Approaches to Korean Cinema', '48L', 'This course explores the postwar development of film in Korea with a focus on the analysis of film form, genre and historical context.', null, 1, null::jsonb),
    ('EAS279H1', 'East Asian Ecocinema', '36L', 'The course examines the ethical, political, historic and aesthetic dimensions of Asian Ecocinema (environmental films that engage with the Asia-based global environmental crisis) and discusses the films'' ways of connecting place and planet.', null, 1, null::jsonb),
    ('EAS284H1', 'Modern Chinese Literature', '24L', 'This course offers a critical examination of 20th-century Chinese literature, with a focus on the important developments of literary writing over time, from the inception of New Literature in the 1910s, the development of realism and modernism in the 1930s, to the emergency of post-revolution and postmodernist writings in the 1990s. Emphasis is placed on generating a dialogue on interpretations of key works.', 'EAS284Y1', 1, null::jsonb),
    ('EAS285H1', 'Revolutions in Modern China', '24L', 'This course offers an interdisciplinary treatment of the Chinese people''s protracted struggle to transform the world''s oldest empire and to create a revolutionary society, with a special focus on the myriad revolutions, uprisings, and protests that had radically remade the country''s social fabric in the tumultuous twentieth century. First-person accounts, classic and revisionist scholarly works, and literary and visual materials will be used to examine China''s multifaceted transformations both chronologically and thematically, in their socioeconomic, cultural, political, and global contexts.', null, 3, null::jsonb),
    ('EAS289H1', 'Environment and East Asia', '24L', 'This course introduces environmental issues that are important to East Asia. Or better put, it examines the role East Asia plays in the global environmental crisis. We engage both the factual and humanities'' dimensions of Climate Change, biodiversity loss, and other urgent environmental crises.', 'EAS289Y1', 3, null::jsonb),
    ('EAS295Y0', 'Topics in East Asian Studies (Summer Abroad)', null, 'This course allows students to pursue the specialized study of specific topics tailored to the research and study opportunities available in Hong Kong and the expertise and interests of the instructor. Available only in the Woodsworth College Hong Kong Summer Program.', null, null, null::jsonb),
    ('EAS296H1', 'Topics in East Asian Studies', '24L', 'A study of Chinese, Japanese or Korean culture, history and/or literature. Content depends on the instructor. When offered, the course will have a subtitle that describes its content.', null, null, null::jsonb),
    ('EAS297H1', 'Texts, Images and Objects in East Asia', '24P', 'This course seeks to understand East Asian civilizations through texts, images, and objects exhibited at the Royal Ontario Museum (ROM). Students study various texts, paintings, bronzes, architecture, sculptures, porcelains, and other objects, and explore their historical, aesthetic, and critical meanings.', null, 1, null::jsonb),
    ('EAS299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EAS299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EAS300Y1', 'Modern Standard Chinese III', '96L/36T', 'This high intermediate-level course is a continuation of  EAS200Y1. Students learn to read short texts which deal with cultural and social topics, compose paragraph-length essays, and converse in social situations which require exchanges of basic information and generate interpretations. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'LGGC60H3,  LGGC61H3,  LGGB62H3,  LGGB63H3,  LGGC62H3,  LGGC63H3,  CHI303H5,  CHI304H5', 1, '{"operator": "OR", "items": ["EAS200Y1"]}'::jsonb),
    ('EAS301H1', 'Modern Standard Chinese III for Students with Prior Background', '48L', 'This course is the equivalent of the second half of  EAS300Y1. It is for students who have either completed successfully  EAS201H1 or reached the intermediate-mid level in speaking, listening, reading and writing by prior study. Successful completion of the course fulfills the prerequisite for  EAS401H1,  EAS402H1, or  EAS404H1.', 'EAS300Y1,  LGGC60H3,  LGGC61H3,  LGGB62H3,  LGGB63H3,  CHI303H5,  CHI304H5', 1, '{"operator": "OR", "items": ["EAS201H1"]}'::jsonb),
    ('EAS307H1', 'Traditional Chinese Political Philosophy', '24L', 'This course explores and evaluates the views of prominent Chinese thinkers and texts from the classical, medieval, and late imperial periods on central issues in political philosophy, including the justification of political authority, the relation between people and the state, the roles and means of government, and the extent of the state''s power over its subjects. We cover a broad selection of materials from different periods in Chinese history, devoting special attention to the specific form that certain philosophically relevant issues take in Chinese political discourse, such as the role of formal standards versus that of character, the interplay between institutions and ethical discretion, the role of education versus legal coercion, and the advantages of central versus local administration. Readings will include selections from the Documents, Guǎnzĭ, Mòzĭ, Analects, Mèngzĭ, Xúnzĭ, Dàodéjīng, Zhuāngzĭ, Hánfēizĭ, Discourses on Salt and Iron, Jī Kāng, Guō Xiàng, Bào Jìng Yán, Luó Yǐn, Oūyáng Xiū, Chéng Yí, Wáng Ānshí, Chéng Hào, Hú Hóng, Chén Liàng, Fāng Xiàorú, Gù Yánwū, Huáng Zōngxī, and Táng Zhēn.', null, 2, '{"operator": "OR", "items": ["EAS105H1", "EAS241H1", "PHL237H1"]}'::jsonb),
    ('EAS308H1', 'East Asia Seen in Maps, Ancient and Modern', '24L', 'Through the lens of important maps ancient and new, this course looks at the histories, cultural logic, and methods of visual representation in societies of East Asia. The maps include archaeological artifacts, ancient manuscripts, and printed renditions, spanning from early history to the nineteenth century.', null, 2, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS309H1', 'Modern Chinese Prose', '24S', 'A survey of representative works of prose written by 20th-century Chinese writers. This course focuses on reading texts, as well as analyzing their textual structures, aesthetic values, and historical contexts.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS310Y1', 'Modern Standard Korean III', '48L/72T', 'As a continuation of  EAS210Y1 and  EAS211Y1, this course is designed to help students improve their Korean proficiency at the intermediate level. The class focuses not only on oral fluency and grammar but also on reading comprehension. Students who do not meet the prerequisite must go through placement process conducted by Department. See www.eas.utoronto.ca/languages/korean for details.', null, 1, '{"operator": "OR", "items": ["EAS210Y1", "EAS211Y1", "EAS212H1"]}'::jsonb),
    ('EAS311H1', 'A History of Japanese Monsters', '24L', 'This course examines the historical development of Japanese monsters, from roughly the 7th - 8th centuries to modern times. We focus on how the changing understanding of monsters in society has embodied certain fissures in Japanese culture, especially with regard to gender and class.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS312H1', 'Art and Archaeology of Early China', '36L', 'This course explores ancient societies from prehistory to the Bronze Age of China from archaeological perspectives with a focus on Chinese collections at the ROM. The course offers students an understanding of the origins and formation of Chinese civilizations.', 'EAS411H1', 1, '{"operator": "AND", "items": ["EAS105H1", {"operator": "OR", "items": ["EAS209H1", "ANT100Y1", "ANT200Y1"]}]}'::jsonb),
    ('EAS313H1', 'Precarious Island: Taiwan in the World', '24L', 'This course is a thematic survey of twentieth- and twenty-first-century Taiwanese literature and culture, set in archipelagoes and oceans caught in the global history of colonialism and imperialism, the twentieth century wars, the unfinished Cold War, environmental crisis, and AI chip war.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS314H1', 'Culture & World After Hiroshima & Nagasaki', '24L', 'Exploration of literature, film, and other cultural production related to the atomic bombing and other nuclear catastrophes from transnational, inter-Asia, and transpacific perspectives. Primarily focuses on, but not necessarily limited to, the cultural texts, intellectual concepts, and social thoughts generated out of the history of Hiroshima and Nagasaki atomic destruction.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS315H1', 'The "Yellow Peril": Past & Present', '24L', 'Beginning with the Chinese Exclusion Acts, the Asian presence in North America has often been considered a serious social menace. This course explores the Asian/North American response to the past and present "Yellow Peril" constituted as a gendered, sexualized, classed, and racialized epistemological and affective structure of knowledge.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS324H1', 'The Asia-Pacific in the Nuclear Age', '24L', 'From the events such as the world''s first use of the atoms for war, the Cold War nuclear arms race, the “Atoms for Peace” campaign, the worst nuclear accident in history, to the unfolding threat of nuclear proliferation, the twentieth century Asia-Pacific region has been profoundly shaped by the nuclear age. The course introduces the diverse cultural knowledge and social thoughts that have developed distinctly in the Asia- Pacific in response to the nuclear-related affairs. They include, for instance, the ideas and practices concerning the environment, the human, peace, visibility, security, coloniality, sustainability, etc.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS327H1', 'Japanese Fiction and the Nation', '24L/4T', 'Explores modern Japanese literature, with special attention given to literature''s relation to the nation. Students explore how literature transforms throughout Japanese modernity and how its meaning and effects function to simultaneously solidify and fracture national identity.', null, 1, '{"operator": "AND", "items": ["EAS105H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('EAS328H1', 'Science, Technology and Society in Modern China', '24L', 'Learn to understand modern China from an understudied yet important perspective: the development of science and technology since the establishment of People''s Republic in 1949. Science and technology have played crucial parts in China''s political, economical, social, and cultural transformations. Drawing from anthropological, social, and historical studies of science, we examine, among other topics, science and nation-building, biopolitics, technocracy, and scientists'' self-fashioning at the junction of Communist reign and global capitalism. Students also learn key concepts of science studies.', null, 3, '{"operator": "OR", "items": ["EAS105H1", "CAS201H1"]}'::jsonb),
    ('EAS329H1', 'Cross-Cultural History of Scents and Aromatics', '24L', 'This course surveys the importance of smell as a form of knowledge and source of history, and explores the use of aromatics in medicine, food, ritual, and personal fragrance, along with their role as a global commodity in East Asia and beyond. Students will read a variety of medieval and early modern texts about aromatics as well as more recent studies on olfaction.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS330H1', 'Narrative Strategies in Modern Japanese Fiction', '24L', 'Discussion of narratives by modern Japanese authors with attention to issues in narratology and contemporary narrative studies such as: voice and perspective; gender and power relationships of the narrator-narratee-narrated; the act of narrating, writing, listening and reading; and metafictional paradox.', null, 1, '{"operator": "AND", "items": ["EAS105H1", {"operator": "OR", "items": ["EAS218H1", "EAS231H1", "EAS235H1", "EAS251H1", "EAS256H1", "EAS257H1", "EAS263H1", "EAS279H1", "EAS284H1", "EAS284Y1", "EAS308H1", "EAS309H1", "EAS327H1", "EAS333H1", "EAS334H1"]}]}'::jsonb),
    ('EAS333H1', 'Modernism and Colonial Korea', '24L', 'This course considers the problem of colonial modernism through a close reading of literary and cultural texts from early 20th-century Korea. It asks what it means to enter modernity under colonial rule, and questions the relationship between imperialism, writing, and subjectivity. Topics include the role of literature in elaborating new concepts of subjectivity, literature and the fine arts as assimilatory practices, the emergence of urban space and reconfiguration of notions of the rural, and changing notions of time and space in the cultural products of nativism. Readings of literary works will be accompanied by showings of paintings and photographs from the period, as well as discussions of theoretical essays on modernism.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS334H1', 'Chinese Novels', '24L', 'This course explores the development of Chinese fiction from earliest times with emphasis on the twentieth century.', 'EAS334Y1', 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS335H1', 'Introduction to Manchu Language and History', '24L', 'This course explores the history of Manchu rule in China''s last imperial dynasty, the Qing (1644–1912), through an introduction to the Manchu language. In addition to learning to read Manchu materials, from imperial court documents to conversation guides and short stories, students will be exposed to a wide range of historical approaches to the study of Manchu social, literary, and political culture, as well as ethnicity in late imperial China.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS338H1', 'Classical Daoism', '48L/24P', 'This course examines major issues of classical Daoist thought, such as Dao and cosmos, body and self, human nature, language and knowledge, and political visions. Based on both textual and ideological analysis of Daoist works such as the Laozi, the Zhuangzi, and Huanglao Daoist texts, to be updated with recently unearthed texts in silk and bamboo slips.', null, 2, '{"operator": "AND", "items": ["EAS105H1", {"operator": "OR", "items": ["PHL237H1", "EAS241H1"]}]}'::jsonb),
    ('EAS340H1', 'Chinese Society and Culture', '24L', 'This course explores issues of identity, self, and community in a broad exploration of cultural transformation in China.', 'EAS340Y1', 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS343H1', 'A History of Sushi', '24L', 'Japan''s most famous foodstuff—and a global commodity—sushi is simultaneously “Japanese” and international. This course uses sushi and other familiar Japanese dishes as a starting point to investigate how food takes on, maintains, or sheds national characteristics in an age of globalization and fusion cuisine. The historical development of sushi offers a perspective on how ideas about Japan and Japaneseness have evolved and about how Japan has interacted with global currents in food and culture.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS345Y1', 'The Rise of Greater China: Issues & Topics', '48L', 'This course looks at China from a regional perspective, with a focus on Taiwan, Hong Kong, and the Peoples Republic of China''s economic integration. The role of Chinese communities globally and in Southeast Asia also receives attention.', 'EAS345H1', 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS347H1', 'Everyday Life in Modern Japan', '24L', 'This course analyzes the history of modern Japan from the perspective of a “critique everyday life” (la vie quotidienne; nichijō seikatsu). Analyzing the uneven transformation of Japan''s feudal society into a capitalist commodity economy, the course discusses how everyday life in Japan was produced and reproduced in ways that are specific to capitalist society, but that also open onto questions of a revolution of everyday life, an everyday life after capitalism. Focusing on different moments in Japan''s modern history (including its past colonial empire), the course looks at, reads, and listens to diverse representations of everyday life in Japan, especially in the worlds of work and labour, consumption and social reproduction. How are these worlds represented politically, as well as aesthetically? Specific topics include: literature and music, architecture and housing, war and forced labour, population control and sexual reproduction, and radio, leisure-time, and state propaganda.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS348H1', 'Gift, Plunder, and Exchange: Japan and World History', '24L', 'This course critically re-evaluates the history and historiography of Japanese capitalism, imperialism/colonialism, and world-empire through the lens of three, distinct “modes of exchange”: gift, plunder, and commodity exchange. Inspired by Kojin Karatani''s The Structure of World History: From Modes of Production to Modes of Exchange (2014), this course explores the emancipatory politics inherent in the critical analysis of modes of exchange, and takes up historical cases from Japan, Hokkaido, Okinawa, Taiwan, Korea, China, and the “Greater East Asian Co-Prosperity Sphere.”', null, 3, '{"operator": "OR", "items": ["EAS105H1", "EAS247H1"]}'::jsonb),
    ('EAS349H1', 'Soundscapes and Modern China', '24L', 'An introduction to sound studies through the case of modern China. The class surveys basic theories of sound studies. It investigates the technological, cultural, and social production of soundscapes in modern China. Topics include the invention of national language(s), the introduction of gramophone, radio, and sound cinema, and the relationship between sound, aesthetics, and power.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS350H1', 'Ideology and Japan', '24L', 'This course analyzes the problem of ideology in relation to the development of capitalism and imperialism in modern Japan. Among the topics analyzed in the course will be: the development of a national ideology in the transition to capitalism, the rise of “ultra-nationalism,” the ideological battles between Communism and fascism, the ideological struggles surrounding the U.S. military occupation of Japan, and the question of national ideology in the postwar period.', null, 3, '{"operator": "OR", "items": ["EAS105H1", "EAS247H1"]}'::jsonb),
    ('EAS350Y1', 'Modern Standard Japanese III', '96S', 'This is a lower intermediate level course for those who have completed  EAS253H1 or  EAS220Y1 or  EAS221H1 with a minimum grade of 70%. All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS320Y1,  EAS322Y0', 1, '{"operator": "AND", "items": ["EAS253H1", {"operator": "OR", "items": ["EAS220Y1", "EAS221H1"]}]}'::jsonb),
    ('EAS354H1', 'Body, Movement, Japan', '24L', 'This course will explore theories and practices of the body and movement in Japan by way of a series of associated territories: From the 17th century walking poetry of Basho to various political resistance movements of the 1960s, from the revolutionary dance experiments of Min Tanaka to Buddhist inspired philosophies of Body-Mind and physics inspired theories of movement by Japanese scientists to the movement of information, people, and capital at the contemporary moment.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS355H1', 'The Art and Politics of Video in Japan', '24L', 'This course will study the history of Japanese video art, beginning in the 1960s (when the Sony Corporation released the first portable video cameras) leading to the contemporary moment in which recording devices (phones, surveillance cameras, computers) and new distribution models (the Internet, public projections) abound. Video art is neither cinema nor television, and its early history is marked by some of the most radical artistic and political experiments in the history of modern Japan. This course will focus on the aesthetics and politics of experimental video with an eye on its global flows and Japan''s central role in its development.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS357H1', 'Mao''s China and Beyond', '24L', 'This course introduces major issues and events in contemporary Chinese history from the success of the Communist revolution in 1949 to China''s postsocialist transitions in the 1980s and early 1990s. Topics include the development and victory of the Chinese Communist revolution, the rule and legacy of Mao Zedong (particularly the Hundred Flowers movement, the Great Leap Forward, and the Cultural Revolution), and economic reform and political repression in the era of Deng Xiaoping.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS358Y1', 'Classical Chinese I', '48S', 'An introduction to the Classical Chinese language with emphasis on grammatical analysis and translation into English. Open only to EAS majors and specialists.', null, 1, '{"operator": "AND", "items": ["EAS103H1", {"operator": "OR", "items": ["EAS100Y1", "EAS101Y1", "EAS200Y1"]}]}'::jsonb),
    ('EAS361H1', 'Zen Buddhism', '24L', 'This course introduces the Zen Buddhist traditions of China, Korea, and Japan. Emphasis is placed on the radical views of history, language, ritual, self, and enlightenment espoused by these traditions. The course also examines issues related to Zen monasticism, the development of koans, and the definition of orthodoxy in both premodern and modern Zen. Students will be asked to explore these and other topics by paying close attention to the historical, doctrinal, and institutional contexts from which they arose.', null, 2, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS362Y1', 'Classical Japanese', '48S', 'Introduction to classical Japanese, followed by readings of various short works by classical authors.', null, 1, '{"operator": "AND", "items": ["EAS220Y1"]}'::jsonb),
    ('EAS363H1', 'Classical Japanese Part I', '24S', 'Introduction to classical Japanese, followed by readings of various short works by classical authors. Covers first half of  EAS362Y1.', 'EAS362Y1', 1, '{"operator": "AND", "items": ["EAS220Y1"]}'::jsonb),
    ('EAS364H1', 'China''s Cultural Revolution: History and Memory', '24L', 'No understanding of contemporary China is possible without understanding the ramifications of the Great Proletarian Cultural Revolution (1966-1976). This course considers this tumultuous episode as a field of historical research and conceptual inquiry. This course critically examines a wide variety of sources, including scholarly accounts, official documents, personal memoirs, oral histories, and literary works.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS365H1', 'Classical Japanese Part II', '24S', 'Introduction to classical Japanese, followed by readings of various short works by classical authors. Covers the second half of  EAS362Y1. Students must seek permission of the instructor to be placed in the course.', 'EAS362Y1', 1, '{"operator": "AND", "items": ["EAS363H1", "EAS220Y1"]}'::jsonb),
    ('EAS370H1', 'Media, Cultural Citizenship, and the Korean Diaspora', '24L', 'This course explores how cultural and ethnic identity in diaspora is constructed in media texts, and how the politics of national identity target various publics. We will examine the work of particular filmmakers, diasporic Korean celebrities in Korea, and digital platforms for producing public visibility, such as YouTube.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS372H1', 'The Postwar, Cold War and Divided Koreas', '24L', 'This research-oriented course examines the divided history of the Korean peninsula since 1945 in the context of the global war. Examines key debates in the history of contemporary Korea, beginning with the Korean war and ending with the contemporary culture of division.', 'EAS372Y1', 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS373H1', 'Revolutionaries, Rebels, and Dissent in Korea''s Long 20th Century', '24L', 'Korea''s long 20th century experienced many tumultuous moments of dissent, rebellion, and revolution. When, why, and how do specific people dissent? This course devotes each weekly meeting to the study of a single moment of dissent, ranging from the peasant uprisings of the 1890s to labor activities in the colonial period and from anti-regime student movements in the 1970s to recent social movements and candlelight demonstrations.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS374H1', 'Modern Japan and the Colonial Question', '24L', 'This course interrogates the history of modern Japan from the perspective of Japan''s colonial exploits in East Asia. The course also addresses the political economy and culture of the military occupation of Japan by the Supreme Command of the Allied Powers. Texts from economics, philosophy, and literature will be used.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS375H1', 'Postwar Japan: Crisis, Apocalypse', '24L', 'This course explores the history of the postwar period in Japan and its former colonies in order to delineate a way to think of the idea of apocalypse in relation to crisis in advanced capitalism. Through an examination of the history of capitalist crisis in postwar Japan, the course investigates themes of apocalypse in atomic-bomb literature, television, Godzilla, radical students movements, ecological-industrial disasters, worker art movements, debates on modernity and fascism, avant-garde theatre, popular music, religious movements, nationalism, populism, and the so-called "ageing population" problem. The course revolves around texts by philosophers, economists, novelists, essayists, artists, and critics, as well as film and audio recordings.', 'EAS347H1,  EAS374H1', 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS378H1', 'Urban Life in Early Modern Japan', '24L', 'An exploration of most important cities of Tokugawa Japan, which were among the largest of the early modern world, and home to vibrant urban culture and economic activity. The texts include buildings, maps, paintings, prints, film and novels.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS380H1', 'Writing Women in Premodern China', '24L', 'A survey of premodern Chinese texts (before 1700) in translation, written by women, about women, and in the voices of women, across a variety of genres drawn from literature, history, philosophy, and religion. The texts provide opportunities to explore how gender was constructed in Chinese societies, how women were defined and constrained by texts, and how women used writing to express themselves, often in resistance to dominant modes of representation.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS381H1', 'Moral Agency in Chinese Thought', '24L', 'The course explores selected Chinese philosophical texts addressing moral motivation, cultivation, reasoning, and action to examine their treatment of how human beings can become morally virtuous and live an ethically ideal or fulfilling life. Topics discussed will include people''s typical moral dispositions; morally relevant features of people''s nature (xìng); the role of the heart (xīn) in guiding action; the role of desire, emotion, and normative judgment in motivation and action; methods of moral education and training; the nature and function of virtue; and the structure of action. In different years, the course may focus on classical texts such as the Mòzǐ, Mèngzǐ, Xúnzǐ, and Zhuāngzǐ or on later Confucian figures from the Sòng, Míng, and Qīng dynasties, such as Chéng Yí, Chéng Hào, Zhū Xī, Lù Xiàngshān, Wáng Yángmíng, and Dài Zhèn.', null, 2, '{"operator": "OR", "items": ["EAS105H1", "EAS241H1", "PHL237H1"]}'::jsonb),
    ('EAS384H1', 'Medieval Japan', '24L', 'In popular culture medieval Japan often figures as an era of unremitting warfare, in which only samurai mattered. This course offers more balanced view of what many historians regard as the most volatile, yet also most creative, era in Japanese history. The course examines the era from 1100-1500 with an eye to understanding the place of warriors, but also to explaining the incredible cultural advances of the period, which gave rise to many of the arts for which Japanese culture is renowned.', null, 3, '{"operator": "OR", "items": ["EAS103H1", "EAS105H1"]}'::jsonb),
    ('EAS386H1', 'Culture of Nature in China', '24L', 'The course examines the cultural practice of nature in China''s past and present, focusing on literary, artistic, spiritual, ethical, political, and scientific aspects of human-nature relation. Through scholarly works and primary sources, the course inquires into the cultural politics of human-nature entanglements.', 'EAS386Y1', 2, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS387H1', 'Images and Ideas in Chinese Art', '24L', 'Making use of the Royal Ontario Museum''s excellent Chinese art collection, this object-based and oriented seminar encourages exploration of the ideas and practices behind works of Chinese art. We examine art and artifacts in relation to their social environment and historical contexts, paying close attention to such issues as political practices, power and authority, identity, gender, and materiality. Other relevant topics include patronage, audience, religious quests, and literati culture. Depending on special Chinese exhibitions of the year at the ROM, the course may incorporate case-studies of relevant exhibition content.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS388H1', 'Asian/North American Feminist Issues', '24L', 'A transpacific examination of gender and sexuality issues that have directly and indirectly affected Asians and Asian North Americans. Considers, for example, the gender and sexual representations of Asia in North America, the psycho-history of the "Yellow Peril" and its ramifications beyond Asian North Americans, and the history of immigration, nationalism, colonialism, war, and the militarized empire.', null, 3, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS389H1', 'Dangerous Bodies: Crossings in Gender and Sexuality Studies', '24L', 'This course examines non-conforming bodies and technologies of self-making that defy gender and racial norms in 20th and 21st century China and Asian America. Through different cross-dressing and other crossing practices in literature, fashion, and history, we explore shifting social meanings of the body, masculinity, femininity, and trans-becoming.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS391H1', 'Transnational East Asian Cinema', '48L', 'This course investigates cinema''s border-crossing modes of production, reception, and circulation, to uncover the ways in which the study of cinema enriches current theories and approaches to the transnational. Films and sites to be explored may include Asian co-productions (documentaries, feature films, shorts), transnational genre adaptations (e.g., The Ring/Ringu), and film festivals.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS392H1', 'East Asian Television', '24L', 'This course approaches television and televisuality in regional, transnational, and global perspectives. Beginning with the cold war histories of transmission infrastructures in the Asia Pacific, continuing with an exploration of key television shows and genres that support and resist the nation-building ethos of the medium, the course will introduce students to the history and ideology of televisuality in East Asia.', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS393H1', 'Chinese Buddhism', '24L', 'Topics vary according to the instructor''s interests.', null, 2, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS394H1', 'Film Culture in Contemporary China', '36L', 'This course discusses documentary film and DV culture in contemporary China as forms of cultural, communal, and political practices. We focus on films and videos that seek to address important global issues such as peace, environment, and climate change in cross-media approach and in personal tone. We ask: What new tendencies are there in the films and videos? Where can we trace them back to? What fresh possibilities do they bring forth to our aesthetic and public life?', null, 1, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS395Y0', 'Topics in East Asian Studies (Summer Abroad)', null, 'This course allows students to pursue the specialized study of topics tailored to the research and study opportunities available in Hong Kong and the expertise and interests of the instructor. Available only in the Woodsworth College Hong Kong Summer Program.', null, null, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS396H1', 'Special Topics in East Asian Studies', '24L', 'A study of Chinese, Japanese or Korean culture, history and/or literature. Content depends on the instructor. When offered, the course will have a subtitle that describes its content.', null, null, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["EAS105H1"]}'::jsonb),
    ('EAS399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EAS399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EAS401H1', 'Modern Standard Chinese IVa', '48L', 'This course aims to develop students'' abilities at an advanced level, with a focus on reading of fictional and/or journalistic writings. Students will improve their reading comprehension, strengthen writing skills, and advance speaking and listening skills through class discussions and oral presentations. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/chinese for details.', 'CHI411H5 and  ECTB61H3', 1, '{"operator": "OR", "items": ["EAS300Y1", "EAS301H1"]}'::jsonb),
    ('EAS402H1', 'Modern Standard Chinese IVb', '48L/24T', 'An advanced Chinese language course which explores major concerns in contemporary China, including mass consumption, Western influences and technological innovation. Students will improve their reading comprehension, strengthen their writing skills and, importantly, advance their speaking and listening abilities through debate exercises. Students who do not meet the prerequisite must go through placement process conducted by the Department. See https://www.eas.utoronto.ca/languages/chinese for details.', 'CHI411H5 and  ECTB61H3', 1, '{"operator": "OR", "items": ["EAS300Y1", "EAS301H1"]}'::jsonb),
    ('EAS403H1', 'Chinese Language in Media', '24L/12T', 'Chinese for users whose proficiency level is at or beyond the highest level that is currently offered. Students develop linguistic skills and cultural competence to understand and research contemporary Chinese mass media, social media, and public discourse. The language of instruction is mostly Chinese – Mandarin.', null, 1, '{"operator": "OR", "items": ["EAS401H1", "EAS402H1", "EAS404H1"]}'::jsonb),
    ('EAS404H1', 'Business Chinese', '48L/24T', 'This course aims to assist students with upgrading their language proficiency for professional purposes. This advanced Chinese language course focuses on 1) business terms and expressions and 2) formal or semiformal discourse in business. Students who do not meet the prerequisite must go through placement process conducted by the Department. See https://www.eas.utoronto.ca/languages/chinese for details.', 'CHI411H5 and  ECTB61H3', 1, '{"operator": "OR", "items": ["EAS300Y1", "EAS301H1"]}'::jsonb),
    ('EAS406Y1', 'Thinking about Things: Material Culture in East Asia', '48S', 'This seminar explores theories of the object, the histories of objects in East Asia, and critical thinking about the process of research. Through theoretical readings, class, and individual research projects, the seminar asks how to formulate research questions, use the internet and other resources, and present discoveries in a class conference.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS407H1', 'Textual Analysis of Classical Chinese Philosophy', '24S', 'Readings from ancient and medieval Chinese philosophy. Beginning with linguistic (especially semantic) analysis of key words, structure and meaning of sentences, paragraphs, and texts as a whole, which forms the basis for philosophical examination.', null, 2, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["PHL237H1", "EAS241H1"]}]}'::jsonb),
    ('EAS408H1', 'Modern Taiwanese Literature', '24S', 'A general survey of modern Taiwanese literature from 1949 to the present. It examines issues central to understanding the Taiwanese literary culture, such as historical/cultural context, oral/written language, self-identification, gender, and human rights.', null, 1, '{"operator": "AND", "items": ["EAS209H1", {"credits": 2.0, "department": "literature"}]}'::jsonb),
    ('EAS409H1', 'Cities in Premodern China', '24S', 'Focusing on selected Chinese cities from the earliest history to 1800 CE, this course introduces students to different aspects of urban life and its representations in literature and history.', 'EAS367H1', 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS410Y1', 'Modern Standard Korean IV', '96L', 'As a continuation of  EAS310Y1, this course is designed for advanced-level learners of Korean. Through reading short essays/articles and watching films, this course aims to improve students'' proficiency in speaking, writing, listening, and reading. Classroom and online discussions are conducted entirely in Korean. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.eas.utoronto.ca/languages/korean for details.', null, 1, '{"operator": "AND", "items": ["EAS310Y1"]}'::jsonb),
    ('EAS412H1', 'Technology and Material Cultures of Ancient China', '24P', 'This course introduces the technology and material culture of prehistoric and Bronze-Age China. Offers students an understanding of the development of ancient technologies (e.g. bronze, jade, and lacquer) and associated ways of life from archaeological perspectives.', null, 3, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["EAS312H1", "EAS411H1"]}]}'::jsonb),
    ('EAS416Y1', 'Academic and Professional Korean', '96L', 'This course aims to assist students to upgrade their language proficiency for academic and professional purposes. It is ideal for students who seek career opportunities in Korea-related business or in higher education in Korean studies. Emphasis is on comprehension and composition of academic and business texts and preparation for Korean proficiency tests. Students who do not meet the prerequisite must go through placement process conducted by the Department. See www.utoronto.ca/languages/korean for details.', null, 1, '{"operator": "AND", "items": ["EAS310Y1"]}'::jsonb),
    ('EAS417H1', 'Korean Literary Translation Workshop', '24L', 'A workshop format is used to explore problems encountered when translating Korean literary texts (fiction and poetry) into English. Practice with a variety of texts is accompanied by readings in translation theory to refine our understanding of translation and enrich our experience working with historical forms of Korean and English.', null, 1, '{"operator": "AND", "items": ["EAS209H1", "EAS310Y1"]}'::jsonb),
    ('EAS418H1', 'Chinese Art Theories', '24S', 'This course focuses on theories of Chinese arts by critically analyzing various theoretical texts and treatises on music, painting, calligraphy, and literature as recorded in the Classics.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS419H1', 'Chinese Cultural Studies Seminar: May Fourth', '24L', 'This seminar focuses on the May Fourth Movement in early twentieth century China. Taking May Fourth as a case study and a vantage point, this class enables a critical understanding of various aspects of the cultural and intellectual life in the early Republican period.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS420H1', 'Travels, Travelers, and Travel Accounts in Asia', '24S', 'This seminar focuses on the circulation of people, words, and ideas throughout Asia before 1900, as we try to understand the worlds travelers both sought and encountered. Texts include travel diaries and geographical narratives.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS421H1', 'History of the Chinese Book', '24L', 'This seminar traces the changing forms of the Chinese book from the early ''page'' to modern print editions. We begin by considering the Chinese writing system and the bones, shells, bamboo and silk on which it was first inscribed. Next, we examine the specific technologies associated with medieval manuscript and early print cultures, many of which were associated with Buddhist textual production. Along the way we consider the social dimensions of Chinese book culture by considering the scribes, binders, engravers, printers, publishers, distributors and readers who produced, circulated and consumed Chinese books. The course draws on the methods and theories developed in diverse fields of study, including book history, philology, literacy studies and archive studies, to examine different chapters in the history of the Chinese book.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS427H1', 'The Kyoto School: Now, Then, and To Come', '24S', 'This course begins with a careful study of a group of modern Japanese thinkers (Nishida, Tanabe, Nishitani) known as the Kyoto School (Kyoto Gaku-ha) who developed their original philosophies by creatively combining the spiritual and intellectual traditions of Mahayana Buddhism with the Western philosophical tradition, most notably with the work of Hegel and Heidegger. We focus on the concept of "Absolute Nothingness" and how it is similar and different to Western ontologies of Being as well as what it implies for political, psychological, spiritual, and artistic life. We also study significant criticisms of the Kyoto School (Tosaka, Miki, et al.) and re-evaluate how such a project persists today as well as how it might make a claim on possible futures.', null, 2, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS431H1', 'Advanced Seminar in Japanese Cinema', '24S', 'The focus ranges from the examination of cross-cultural theoretical problems (such as Orientalism) to a director-based focus, from the examination of genre (such as documentary or the category of genre itself) to the way film intersects with other cultural forms and technologies (such as video and new media).', null, 1, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["EAS242H1", "EAS243H1"]}]}'::jsonb),
    ('EAS432H1', 'Korean Cultural Studies Seminar', '24S', 'This seminar provides an opportunity for in-depth reading and research into a specific topic in the cultural and intellectual history of Korea. Topics will vary each semester but may include colonial period print culture, the New Woman, the history of photography, and modernism.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS433H1', 'Chinese Cultural Studies Seminar: Land', '24S', 'Land as part of the Earth is repeatedly reconfigured in China throughout the 20th century, first by the Reformists and pioneers of the New Culture, then by geoscientists and writers, as well as by economic planners and social thinkers of recent decades. This seminar provides a critical review of this multi-dimensional cultural and conceptual practice of land, as well as its possible role in the era of climate change.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS434H1', 'Independent Studies', null, 'A scholarly project chosen by the student, approved by the Department, and supervised by one of its instructors. Consult the website (eas.utoronto.ca) for more information. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": "EAS"}, "EAS209H1"]}'::jsonb),
    ('EAS435H1', 'Independent Studies', null, 'A scholarly project chosen by the student, approved by the Department, and supervised by one of its instructors. Consult the website (eas.utoronto.ca) for more information. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": "EAS"}, "EAS209H1"]}'::jsonb),
    ('EAS436Y1', 'Independent Studies', null, 'A scholarly project chosen by the student, approved by the Department, and supervised by one of its instructors. Consult the website (eas.utoronto.ca) for more information. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": "EAS"}, "EAS209H1"]}'::jsonb),
    ('EAS439H1', 'The Global Bildungsroman: Narratives of Development, Time, and Colonialism', '24S', 'This course studies Bildungsroman, the story of an individual''s coming of age, in the context of twentieth-century political, cultural, and social developments of imperialism, anti-colonialism, human rights discourse, and globalization. Our focus will be novels from the (post)colonial world and theoretical essays on the Bildungsroman form. The course aims to provide a model for rethinking literary history and genres within a global context. Authors may include Yi Kwangsu, Wu Zhouliu, Pramoedya Ananta Toer, Kang Younghill, Tsitsi Dangarembga, Camara Laye, amongst others.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS444H1', 'The City, Body and Text in Modern Japanese Literature', '24S', 'This course examines how the city and body exert formative forces on the text, and how the practice of writing and reading texts informs the ways we, as corporeal beings, experience the city as manifested in the 20th-century Japanese literature.', null, 1, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["EAS218H1", "EAS231H1", "EAS235H1", "EAS251H1", "EAS256H1", "EAS257H1", "EAS263H1", "EAS279H1", "EAS284Y1", "EAS308H1", "EAS309H1", "EAS327H1", "EAS330H1", "EAS333H1", "EAS334H1", "EAS334Y1", "EAS408H1", "EAS409H1", "EAS417H1", "EAS419H1", "EAS467H1"]}]}'::jsonb),
    ('EAS445H1', 'Fascism and Japan', '24S', 'This seminar analyzes fascism in modern Japan: its ideology, theories, and practices. We define fascism as a symptom of imperialism, and also explore the critique of fascism in Japan by Japanese thinkers on the Left, such as Tosaka Jun, whose Japanese Ideology represents one of the most trenchant critiques of fascism.', null, 2, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS446H1', 'The Communist Hypothesis and Asia', '24L', 'In recent years, the basic hypotheses of Communism have begun to be thought anew, precisely because of the demise of the Soviet Union and the rise of capitalism in communist regimes (i.e., China). Taking up recent writings by Alain Badiou, Jodi Dean, Gavin Walker, Fred Jameson and a host of other contemporary thinkers, this course asks again: what is the communist hypothesis in today''s Asia and how can it help us to imagine a different Asia?', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS447H1', 'Sound Studies and Modern Japan', '24S', 'This seminar explores the growing field of sound studies with particular attention given to auditory histories and cultures in modern Japan and the prewar Japanese empire in East Asia. We study the interrelationships between industrialization, mass culture, colonialism, and techniques and processes of reproducing sound in order to specify the status of acoustic and sonic mediation in everyday life in a capitalist commodity economy.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS448H1', 'East Asian Studies Archive: Language, Number, Money', '24S', 'This course investigates salient problems of the historical archive in relation to the experience of modernity in East Asian societies. What is the meaning of the modern archive in East Asia? How is the knowledge of the modern archive produced in relation to the production of quantitative knowledge (e.g., in demographic or economic statistics)? How should we approach the relationship between number and language? How is this knowledge transformed into state knowledge as well as into what we call common sense?', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS449H1', 'Future, Architecture, Japan', '24L', 'Examination of how the future is imagined and materialized in architectural theory and practice throughout Japanese history. From classical temples to modernist experiments of the Metabolist movement to contemporary works by Isozaki Arata and Atelier Bow Wow, we study built and unbuilt structures as theories of the future.', null, 1, '{"operator": "OR", "items": ["EAS209H1", "ARC221H1"]}'::jsonb),
    ('EAS450H1', 'History of the USA in the Pacific, the 19th century', '24S', 'This course examines the growth of the American empire in Asia Pacific during the late 19th century. It examines historical writings concerning Japan, Korea, Hawaii, the Philippines, and China.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS451H1', 'Modern Standard Japanese IV-a', '48S', 'This is an upper intermediate level Japanese course that focuses on reading and writing skills for those who have completed  EAS350Y1 (previously  EAS320Y1) with a minimum grade of 70%. Native or near-native speakers are not permitted to take this course. All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS461H1,  EAS463Y0', 1, '{"operator": "OR", "items": ["EAS350Y1", "EAS320Y1"]}'::jsonb),
    ('EAS452H1', 'The Korean War, Global Cold Wars, and Decolonization', '24S', 'This course examines the political economic, racial, and cultural dimensions of the Korean war in a global context. It examines how the Korean War consolidated Cold War structures and discourse on both sides of the conflict by examining such issues as the United Nations, multiculturalism, decolonization, atomic weapons, and military industrialization. In this writing intensive course, students will be expected to write a major research paper.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS453H1', 'Modern Standard Japanese IV-b', '48S', 'This is an upper intermediate level Japanese course that focuses on oral/aural communication for those who have completed  EAS350Y1 (previously  EAS320Y1) with a minimum grade of 70%. Native or near-native speakers are not permitted to take this course. All students must go through a screening process conducted by the Department. See https://www.eas.utoronto.ca/languages/japanese for details.', 'EAS460H1,  EAS463Y0', 1, '{"operator": "OR", "items": ["EAS350Y1", "EAS320Y1"]}'::jsonb),
    ('EAS454H1', 'Modern Chinese Historiography', '24S', 'A selective survey of major historiographical problems and debates in the fields of late 19th and 20th century Chinese history. Course readings will include both theoretical and historical materials.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS455H1', 'Classical Confucianism', '24S', 'This course explores the historical and systematic aspects of classical Confucianism, which is fundamental for understanding Chinese philosophy and culture. The historical part discusses the development of the Confucian doctrine from Confucius to his generations of disciples. The systematic part engages issues such as emotion, art, poetry, morality and virtues, political philosophy, and knowledge and reality.', null, 2, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["EAS241H1", "PHL237H1"]}]}'::jsonb),
    ('EAS456H1', 'Japan as seen by ?: Reference, Apparatus, Operation', '24S', 'The course discusses how images of Japan, charged with varied degrees of desire for empirical knowledge, have contributed to contemporary novels and plays by David Mitchell, Ruth L. Ozeki, David Mamet, Joy Kogawa, Kazuo Ishiguro, Marguerite Duras, and David Hwang.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS457H1', 'Modern Japanese Historiography', '24S', 'An analysis of contemporary monographs on modern Japanese history. This course offers a critical survey of existing methodologies of and approaches to writing about modern Japan.', null, 3, '{"operator": "AND", "items": ["EAS209H1", "EAS247H1"]}'::jsonb),
    ('EAS458H1', 'Classical Chinese II', '24S', 'As a continuation of  EAS358Y1 (formerly  EAS206Y1), this course helps students to gain in-depth control of grammatical structures of classical Chinese and to read texts with greater ease. Requirements include a major research/translation project. Open only to EAS majors and specialists.', 'EAS306Y1,  EAS335Y1', 1, '{"operator": "AND", "items": ["EAS358Y1"]}'::jsonb),
    ('EAS459Y1', 'Rethinking the Cold War in East Asia', '48S', 'This research course examines the ways our historical understanding of the Cold War in East Asia has shifted over the last twenty years. Focusing primarily on the divided Korean peninsula where it can be said the Cold War still rages, the course examines the mutual constitution of two competing regional political economies rooted in a shared commitment to developmentalism.', null, 3, '{"operator": "AND", "items": ["EAS209H1", "EAS271H1"]}'::jsonb),
    ('EAS465H1', 'Korea Under Japanese Colonialism', '24S', 'This seminar introduces students to comparative studies of colonialism, focusing on Japanese colonialism in Korea. Students will read broadly in the historiography of the Japanese Empire with the goal of developing an understanding of trends that have shaped the research directions of the last ten years. Part of the course will also include readings in and discussion of comparative colonialism. The final statement will be an intensive state-of-the-field paper.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('EAS466H1', 'Rethinking North Korean History', '36S', 'This essay-driven course explores the complexity of examining North Korean history by using comparative methods developed through the study of other socialist societies and theories of everyday life.', null, 3, '{"operator": "AND", "items": ["EAS209H1", "EAS271H1"]}'::jsonb),
    ('EAS467H1', 'Photographic Narratives of Japan', '24S', 'Uses seminal theoretical literature, photo roman (by, e.g., Abe, Nakagami) and narratives about photography (by, e.g., Tanizaki, Mishima, Kanai) to examine the rhetorical complicity and coercion of the two modes of representation which emerged in the modern and nationalistic age, and persist, in the wake of the newer media, as dominant registers of everyday life and departures from there.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS468H1', 'Democratic Struggles in Korea', '24S', 'This seminar examines resistance, struggles, strikes and movements seen as constituting a troubled history of democracy across Korea''s long 20th century.', null, 3, '{"operator": "AND", "items": ["EAS209H1", "EAS271H1"]}'::jsonb),
    ('EAS470H1', '“Post-Fukushima” Literature and Culture', '24S', 'The course examines literature, film, and other cultural products that emerged in the aftermath of the earthquake and tsunami that hit Northeast Japan on March 11, 2011, as well as in the ensuing nuclear crisis at the Fukushima Tokyo Daiichi powerplant. We will explore the distinctive aesthetic forms and imaginaries that responded to such natural and human-made disasters.', null, 1, '{"operator": "AND", "items": ["EAS209H1", "EAS320Y1", {"credits": 1.0, "department": "EAS"}]}'::jsonb),
    ('EAS471H1', 'Issues in the Political Economy of South Korea', '24S', 'A course designed to guide students toward a research paper on a selected topic of interest on the postwar political economy of South Korea.', 'EAS471Y1', 3, '{"operator": "AND", "items": ["EAS209H1", "EAS271H1"]}'::jsonb),
    ('EAS473H1', 'Modern Korean Historiography', '24S', 'An examination of recent literature in the modern Korean history field, focusing especially on the late 19th and 20th centuries.', null, 3, '{"operator": "AND", "items": ["EAS209H1", "EAS271H1"]}'::jsonb),
    ('EAS474H1', 'U.S. and Canada''s Wars in Asia', '24S', 'This course examines the cultural and social legacies of the 19th- and 20th-century hot and cold wars fought by the U.S. and Canada in different parts of Asia. It explores film, literature, and other cultural products that came out of the transpacific violence and its aftermath.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS475Y1', 'Issues in East Asian Historiography', '48L', 'This course analyses select topics in the historiography of East Asian. Students are expected to write a major research paper.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS476H1', 'Social Protest in Modern East Asia', '24L', 'This course explores cases of social protests in 19th and 20th century China, Japan, and Korea. Students will read and write about specific case studies of anti-government student protests, labor actions, anti-colonial movements, women''s rights activism, and peasant rebellions.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS477H1', 'Samurai Culture', '24S', 'An intensive seminar exploring one of Japan''s most recognizable figures, the samurai. This course investigates the historical reality of warrior life along with the legends, with focus on the ways in the warrior''s world found expression in religion, art, and literature.', 'EAS478Y1', 3, '{"operator": "AND", "items": ["EAS209H1", {"operator": "OR", "items": ["EAS245H1", "EAS246H1", "EAS247H1"]}]}'::jsonb),
    ('EAS479H1', 'Ecocriticism', '24L', 'The course aims to establish students'' ability to engage with core ecological agendas with methodology of cultural history and literary and visual analysis.', null, 3, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS486H1', 'Readings in Mahāyāna Sūtra Literature', '24S', 'This seminar explores the key literary, doctrinal and ritual innovations of the Mahāyāna Buddhist tradition as it unfolded in the first few centuries of the Common Era. The semester will begin with a consideration of the origins of the Mahāyāna in early India, and end in medieval Mahāyāna communities of East Asia and Tibet. Along the way we will conduct close readings of several important Mahāyāna works (sūtras, commentaries, ritual manuals) in order to explore key elements in the development of the Great Vehicle as it was transmitted and transformed across Buddhist Asia.', null, 2, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS488H1', 'Fandom, Transmedia, and the Korean Wave', '24S', 'This course investigates the transmedia forms and reception contexts of what is now known as hallyu or "the Korean wave." Topics include fan subjectivity and the “global popular,” across a broad array of texts, including music, feature films, television dramas, fan blogs, and internet video. This seminar considers how popular media shape collective identity, and explores the connections between activism, mass media, commodity culture, and their corresponding affective registers, bridging fan studies, media studies, and contemporary Korean cultural studies.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS489H1', 'Advanced Seminar in Asian Media Studies', '24S', 'Topics include: histories of media infrastructures, material culture, geopolitics of colonialism, imperialism, and regionalism, institutional histories of media production, analyses of popular and industrial media practices, questions of interface, platforms, circulation, and reception, and the constitutive role of media in shaping notions of modernity, publicity, and politics.', null, 1, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('EAS496H1', 'Advanced Topics in East Asian Studies', '24S', 'An in-depth study of Chinese, Japanese or Korean culture, history and/or literature. Content depends on the instructor. When offered, the course will have a subtitle that describes its content.', null, null, '{"operator": "AND", "items": ["EAS209H1"]}'::jsonb),
    ('ECO101H1', 'Principles of Microeconomics', '24L/12T', 'An introduction to economic analysis and its applications: price determination, market structure, decision making by individuals and firms, public policy. NOTE: extensive use of graphical and quantitative analysis.', 'ECO105Y1,  ECO100Y5,  ECO101H5,  MGEA01H3,  MGEA02H3,  PPG201H1', 3, null::jsonb),
    ('ECO102H1', 'Principles of Macroeconomics', '24L/12T', 'An introduction to economic analysis and its applications from a macroeconomic (economy-wide) perspective. Topics covered include international trade and finance, role of money and the banking system, monetary and fiscal policy. Note: graphical and quantitative analysis are used extensively.', 'ECO105Y1,  ECO100Y5,  ECO102H5,  MGEA05H3,  MGEA06H3', 3, '{"operator": "OR", "items": ["ECO101H1", "ECO101H5", "MGEA02H3"]}'::jsonb),
    ('ECO105Y1', 'Principles of Economics for Non-Specialists', '48L/24T', 'Fundamentals for consumers, businesses, citizens. Microeconomics focuses on cost/benefit analysis: gains from trade, price coordination, competition/monopoly, efficiency/equity tradeoffs, government/market failures, environmental policies, income/wealth distributions. Macroeconomics focuses on: GDP growth, unemployment, inflation, monetary/fiscal policies, business cycles, exchange rates, government deficits/debt, globalization. Emphasizes economic literacy, fewer mathematical tools than  ECO101H1,  ECO102H1.', 'ECO101H1,  ECO102H1,  ECO100Y5,  ECO101H5,  ECO102H5,  MGEA01H3,  MGEA02H3,  MGEA05H3,  MGEA06H3', 3, null::jsonb),
    ('ECO196H1', 'An Economist''s Guide to the Galaxy', '24S', 'Climb aboard as we seek answers to the "Ultimate Question of Life, the Universe, and Everything" (Douglas Adams). Unlike the Hitchhiker''s Guide to the Galaxy, the answer will not be 42. Prepare for a wide-ranging journey into the questions economists seek to answer and the evidence they muster to examine these questions. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ECO197H1', 'Seminar on Classical Economic Thought', '24L/12T', 'This seminar examines the basic ideas of the five most notable economic thinkers before 1870: Aristotle, Adam Smith, Thomas Malthus, David Ricardo, and Karl Marx. We focus on demand as the basis of price in Aristotle; the ambiguity in Smith between a labour theory of value and a demand/supply theory of value; the principle of population in Malthus; Ricardo''s labour theory of value and his theory of rent and economic growth; and Marx''s labour theory of value as the explanation for the development of capital. The understanding in these authors of economics as an historical process of production gives fascinating insights into modern economic development that contrast with the modern economic concentration on the distribution of resources in a world of scarcity. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ECO198H1', 'Seminar on Modern Economic Thought', '24L/12T', 'This seminar examines the development of modern economic thought from the marginal revolutionaries (Jevons and Menger) who proclaimed that demand in the form of utility was the basis of price to the supply/demand analysis of Alfred Marshall that established modern microeconomics by 1890. We then look at Irving Fisher''s 1907 foundation of the modern concept of the interest rate and the present value of capital before reviewing J.M. Keynes'' 1936 criticism of neo-classical positions on full employment and interest rates in arguing for government manipulation of interest rates to ensure full employment. We finish with Milton Friedman''s championing of the unregulated market economy through his quantity theory of money critique of Keynes. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ECO199H1', 'Economics and Sustainable, Green Development', '24L/12T', 'Economic growth has been a powerful force through history in improving living standards throughout the world. At the same time, there is a growing recognition that environmental damages frequently accompany this growth, whether it be at the local level (soil degradation and deforestation), or the global level (climate change). Economics studies the allocation of scarce resources, but how can it incorporate "the environment" in a meaningful way that can help guide policy-makers in the 21st century? This course is a fast review of economic approaches and tools, and a review of a wide range of environmental policies, designed to manage the possible adverse impacts of economic expansions. The major emphasis in this course is on the market-based policies that guarantee incentive compatibility of these policies, thus, a higher chance of success. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ECO200Y1', 'Microeconomic Theory', '48L/24T', 'Theory of markets and prices. Determination of prices through the interaction of the basic economic units, the household as consumer and as supplier of inputs and the business firm as producer and as employer of inputs. The pricing system as the mechanism by which social decisions and allocation of goods are made in a market economy.', 'ECO204Y1,  ECO206Y1,  ECO200Y5,  ECO204Y5,  ECO205Y5,  ECO206Y5,  MGEB01H3,  MGEB02H3,  MGEC02H3', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO202Y1', 'Macroeconomic Theory and Policy', '48L/24T', 'Theory of output, employment and the price level; techniques for achieving economic stability; central banking and Canadian financial institutions and markets; foreign exchange markets and the exchange rate. This course is not intended for students enrolled in the BCom program; please see  ECO209Y1.', 'ECO208Y1,  ECO209Y1,  ECO202Y5,  ECO208Y5,  ECO209Y5,  MGEB05H3,  MGEB06H3,  MGEC06H3', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO204Y1', 'Microeconomic Theory and Applications (for Commerce)', '48L/24T', 'The use of microeconomics to analyze a variety of issues from marketing and finance to organizational structure. Consumer preferences and behaviour; demand, cost analysis and estimation; allocation of inputs, pricing and firm behaviour under perfect and imperfect competition; game theory and public policy, including competition policy. Business cases are used to connect theory and practice and to highlight differences and similarities between economics and accounting, marketing and finance. This course is restricted to students in the Commerce programs.', 'ECO200Y1,  ECO206Y1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO206Y1', 'Microeconomic Theory', '48L/24T', 'This course deals more rigorously and more mathematically with the topics included in  ECO200Y1 and is intended primarily for students in certain Economics Specialist programs.', 'ECO200Y1,  ECO204Y1,  ECO200Y5,  ECO204Y5,  ECO205Y5,  ECO206Y5,  MGEB01H3,  MGEB02H3,  MGEC02H3', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO208Y1', 'Macroeconomic Theory', '48L/24T', 'This course deals more rigorously and more mathematically with the topics included in  ECO202Y1 and is intended primarily for students in certain Economics Specialist programs.', 'ECO202Y1,  ECO209Y1,  ECO202Y5,  ECO208Y5,  ECO209Y5,  MGEB05H3,  MGEB06H3,  MGEC06H3', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO209Y1', 'Macroeconomic Theory and Policy (for Commerce)', '48L/24T', 'Macroeconomic issues relevant for commerce students. Analytical tools are used to examine policy issues: Canadian government budgets, Bank of Canada monetary policy, exchange rate policy, foreign trade policy and government regulation of financial intermediaries. This course is restricted to students in the Commerce programs.', 'ECO202Y1,  ECO208Y1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO210H1', 'Mathematical Methods for Economic Theory', '24L/12T', 'An introduction to mathematical methods commonly used in economic theory. Topics include: multivariate calculus, concavity and convexity, unconstrained multivariate optimization, multivariate optimization subject to equality or inequality constraints and differential equations.', 'MAT235Y1,  MAT237Y1', null, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO220Y1', 'Introduction to Data Analysis and Applied Econometrics', '48L/48T', 'Numerical and graphical data description; data collection and sampling; probability; sampling distributions; statistical inference; hypothesis testing and estimation; simple and multiple regression analysis (extensive coverage). Learn how to analyze data and how to correctly interpret and explain results. Use Excel to analyze a wide variety of data and replicate tables and figures in economics research papers.', 'GGR270H1,  IRW220H1,  PSY201H1,  PSY202H1,  SOC202H1,  SOC252H1,  STA220H1,  STA221H1,  STA248H1,  ECO220Y5,  MGEB11H3,  MGEB12H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO225H1', 'Big-Data Tools for Economists', '24L/12T', 'An introduction to the big-data tools—including Machine-Learning techniques—economists increasingly use in applied research. The course explores unstructured data sources such as text files, webpages, social media posts, satellite imagery, and weather data. It offers a practical introduction to creating datasets from these sources (e.g., web scrapping), linking data, and managing and visualizing them (e.g., geospatial visualization).', 'CSC311H1,  ECO250Y0 (Special Topics Abroad in Economics: Big Data Tools and Machine Learning for Economists) taken in Summer 2023, ESC190H1,  JSC270H1,  STA314H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC148H1"]}]}'::jsonb),
    ('ECO227Y1', 'Foundations of Econometrics', '48L/24T', 'A rigorous introduction to probability and mathematical statistics intended for students in Economics Specialist programs. Probability and estimation theory, sampling distributions, hypotheses testing, multiple regression analysis. Students will learn the tools used in economics and finance to model and address randomness and uncertainty.', 'STA237H1,  STA238H1,  STA247H1,  STA248H1,  STA255H1,  STA257H1,  STA261H1,  ECO227Y5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}, {"operator": "AND", "items": ["MGEA02H3", "MGEA06H3"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO231H1', 'Economics of Global Trade', '24L/12T', 'This course is intended primarily for students in the International Relations program. This course offers an introduction to the economic causes and consequences of international trade in goods, services, labour, innovation and capital. Attention will be devoted to the economic impact of policies that affect these flows, such as protectionism and outsourcing.', 'ECO230Y1,  ECO364H1,  ECO364H5', 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}'::jsonb),
    ('ECO232H1', 'Global Macroeconomics and Policies', '24L/12T', 'This course is intended primarily for students in the International Relations program. The course serves as an introduction to some of the causes of differences in economic performance across countries and the impact of a variety of government policies, such as monetary and fiscal policy as well as exchange rate regimes, and how each of the three interact in response to changes in development, sovereign debt, monetary unions and financial crises.', 'ECO230Y1,  ECO365H1,  ECO365H5', 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}'::jsonb),
    ('ECO250Y0', 'Special Topics Abroad in Economics', '48L/24T', 'Special Topics in Economics offered in an international setting. Course content and destination may vary. For more information see the Summer Abroad website.', 'ECO250Y0 (Summer 2023) has an exclusion to  ECO225H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1", "ECO100Y5", {"operator": "AND", "items": ["ECO101H5", "ECO102H5"]}]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ECO250Y1', 'Special Topics in Economics', '48L/24T', 'Courses may be offered in one or more subjects each year. Students must meet the prerequisites announced by the Department.', null, null, null::jsonb),
    ('ECO251H1', 'Special Topics in Economics', '24L/12T', 'Courses may be offered in one or more subjects each year. Students must meet the prerequisites announced by the Department.', null, null, null::jsonb),
    ('ECO252H1', 'Special Topics in Economics', '24L/12T', 'Courses may be offered in one or more subjects each year. Students must meet the prerequisites announced by the Department.', null, null, null::jsonb),
    ('ECO295H1', 'Independent Study', null, 'This is an independent study course for students enrolled in an Economics program under the direction of a Department of Economics faculty member. It is an opportunity to explore a topic of interest through readings, discussion, written assignments, experiential learning, etc. This course is open only when a faculty member is available and willing to supervise on an individual basis. Applications will be jointly reviewed by the faculty member and Associate Chair, Undergraduate Studies. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ECO299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO306H1', 'American Economic History', '24L/12T', 'A survey of American economic history from the ante-bellum period to the present. Potential topics include: the rapid growth of the American economy in the late 19th and early 20th century; causes of the onset of the Great Depression; the economic impact of slavery and its aftermath; health and demographic trends; and 20th century trends in inequality.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO310H1', 'Empirical Industrial Organization', '24L/12T', 'The quantitative analysis of firms'' strategies in real-world industries, using tools from applied microeconomics and statistics. Topics include: studies of monopoly, oligopoly, imperfect competition, and the estimation of demand and cost functions that underpin these markets. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites, and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO313H1', 'Environmental Economics and Policies', '24L/12T', 'This course demonstrates how a rigorous application of microeconomic techniques can inform our responses to various environmental problems. Topics may include: air and water pollution and renewable resource management.', 'ECO313H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO314H1', 'Energy and the Environment', '24L/12T', 'This course surveys important features of energy markets and related environmental challenges. One of the central objectives is to provide an understanding of the key economic tools needed to analyse these markets. A related objective is the development of a framework for understanding the public discourse on energy and the environment. Topics include: the hydrocarbon economy (oil, natural gas and coal), electricity markets, global warming and other externalities, renewable energy, conservation, carbon taxes and ''cap-and-trade''.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO316H1', 'Applied Game Theory', '24L/12T', 'Focuses on the core ideas and concepts of game theory and on applications of them in economics and other social sciences. Topics may include: oligopoly, electoral competition, the theory of public goods, voting theory, the free rider problem, repeated interaction, bargaining, evolutionary equilibrium, matching and auctions. Note: This course cannot be taken as a substitute in programs that require  ECO326H1.', 'ECO326H1,  ECO326H5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO317H1', 'Concepts of Fairness in Economics', '24L/12T', 'How can we make collective decisions fairly? What does it mean to properly balance conflicting interests? How can we combine the well-being of individuals into a concept of societal well-being? We explore these and related ethical questions from the perspective of economic theory. A central tool is the axiomatic approach, which calls for decisions to be consistent, in precise senses, across related situations. Possible topics include: rationing problems, the Shapley value, fair division, discrimination, voting theory, foundations of utilitarianism and egalitarianism, measurement of inequality, population ethics, intergenerational equity, and concepts of equal opportunity.', 'ECO351H1 (Special Topics in Economics: Principles of Fair Decisions) taken Fall 2021, Winter 2022, Fall 2022, and Winter 2023', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO320H1', 'Economic Analysis of Law', '24L/12T', 'The practical application of microeconomic theory to common legal problems: torts, contracts, property and crime, and the limitations of economic analysis. No previous familiarity with the law is assumed. (This is an economic analysis of legal issues, not a course in law).', 'ECO320H5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO321H1', 'Canadian Economic History prior to 1850', '24L/12T', 'This course applies the tools of economics - theoretical and empirical - to study Canada''s historical growth experiences. Topics include: the variation in well-being among Indigenous peoples (both pre and post contact), migration and indentured servitude, colonial money, child labour and education, and the rise of factories. The impact of colonial institutions on Canada''s economic success is studied in a comparative context.', 'ECO322Y5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO322H1', 'Canadian Economic History, 1850-1960', '24L/12T', 'Canadian economic history between 1850 and 1960, with a focus on the debate over the ability of the market mechanism to optimize economic development. Topics covered include: tariff policies, Confederation, the transcontinental railroad, opening the West, the Great Depression, monetary policy and the Bank of Canada, regional growth and dominion-provincial relations.', 'ECO322Y5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO324H1', 'Economic Development', '24L/12T', 'This course critically analyzes issues related to economic development and the associated policy responses. Tools from micro and macroeconomic theory are employed, as well as the critical assessment of empirical evidence. Topics may include: education, health, credit markets, inequality, and the role of foreign aid.', 'ECO324H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO325H1', 'Advanced Economic Theory - Macro', '24L/12T', 'A development of the microeconomic foundations of macroeconomic theory to expand students'' analytic skills by constructing and solving macroeconomic models. Topics may include: dynamic choice, neoclassical growth theory, uncertainty and rational expectations, business cycles, as well as fiscal and monetary policy.', 'ECO325H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO208Y1", "ECO202Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO326H1', 'Advanced Microeconomics - Game Theory', '24L/12T', 'Game theory and applications. Topics include: strategic and extensive games, with applications to economics.', 'ECO316H1,  ECO326H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO331H1', 'Behavioural and Experimental Economics', '24L/12T', 'Ample empirical and experimental evidence suggests significant departures from classical assumptions of economic behaviour. For example, humans are neither always perfectly rational nor always self interested. This course describes systematic ways in which behaviour deviates from neoclassical assumptions, generating new, and hopefully more realistic behavioural assumptions that have broad empirical, theoretical and policy implications.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO332H1', 'Economics of the Family', '24L/24T', 'A use of microeconomics to study the behaviour of the family, including marriage, divorce, intra-family allocations, investment in children and gender roles.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO333H1', 'Urban Economics', '24L/12T', 'Spatial economic theory and urban public policy: firms and individuals in partial and general equilibrium, land development and land-use controls, urban transportation, efficiency and equity in spending and taxing.', 'ECO333H5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}'::jsonb),
    ('ECO334H1', 'The Political Economy of Media', '24L/12T', 'We develop tools to analyze voters and the role of information in democracies. Theories of voter information are evaluated using empirical literature on media its political economy. We explore the effects of information-technology innovation, evaluating how the empirical results square with the theory. We focus on empirical methods used to identify the effects of media—from newspapers, radio and television to the internet and social media—on voters. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO336H1', 'Public Economics', '24L/12T', 'Theory of taxation and public goods, and quantitative methods for program evaluation. Additional topics include: taxation and income distribution; environmental policy; and the political economy of government policy.', 'ECO336H5,  ECO337H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO337H1', 'Public Economics (for Commerce)', '24L/12T', 'An introduction to the economics of government similar to  ECO336H1, but with greater focus on issues in business and financial economics. Additional topics include: business tax planning and corporate financial policy; taxation of saving and risk-taking; and government business enterprises.', 'ECO336H1,  ECO336H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO338H1', 'Economics of Careers', '24L/12T', 'The economic analysis of careers from the perspectives of both workers and employers. How do people decide what to study, what careers to pursue, and when to change jobs? How do these decisions interact with the structure of firms? The impact of specialization and the division of labour on the evolution of careers is considered, as are the role of cognitive and communication skills in the labour market.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO339H1', 'Labour Economics: Employment, Wages and Public Policy', '24L/12T', 'Using tools from microeconomic theory and statistics, this course introduces students to the study of labour markets, focusing on employment and wage determination, and the application of labour economics to public policy. Topics may include: labour supply, labour demand, estimating the impact of welfare programs, minimum wages, and other labour market interventions. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', 'ECO343H5,  ECO344H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO340H1', 'Labour Economics: The Distribution of Earnings', '24L/12T', 'Using tools from microeconomic theory and statistics, this course studies the determinants of wages across labour markets. Topics include: the theory of compensating differentials, human capital, discrimination, immigration, unions, and alternative models of compensation. In addition, students are introduced to microeconomic models of unemployment. Throughout the course, there is an emphasis on the evaluation of empirical evidence. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', 'ECO343H5,  ECO344H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO341H1', 'The Economic History of the 20th Century: Trade, Migration, Money and Finance before 1945', '24L/12T', 'Tailored to advanced students in Economics, Commerce, International Relations and History. The focus is on growth and fluctuations in Europe and North America between roughly 1870 and 1939, with a particular emphasis on international trade and payments, migration, investment, and monetary arrangements.', 'ECO303H5', 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["ECO230Y1", {"operator": "AND", "items": ["ECO231H1", "ECO232H1"]}]}, {"operator": "OR", "items": ["POL208Y1", "POL208H1"]}]}]}'::jsonb),
    ('ECO342H1', 'Twentieth Century Economic History: Institutions, Growth and Inequality', '24L/12T', 'Tailored to advanced students in Economics, Commerce, International Relations and History. The focus is on institutions, growth and inequality in countries across the world.', null, 3, '{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["ECO230Y1", {"operator": "AND", "items": ["ECO231H1", "ECO232H1"]}]}, {"operator": "OR", "items": ["POL208Y1", "POL208H1"]}]}]}'::jsonb),
    ('ECO349H1', 'Money, Banking and Financial Markets', '24L/12T', 'This course studies the interaction of the monetary and banking sectors with financial markets and the broader economy. It builds especially on tools developed in intermediate macroeconomics, but also focuses on the institutional structure of the Canadian monetary sector, including the role and operation of the Bank of Canada.', 'ECO348H5/  ECO349H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO350Y1', 'Special Topics in Economics', '48L/24T', 'Courses may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO351H1', 'Special Topics in Economics', '24L/12T', 'Courses may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO352H1', 'Special Topics in Economics', '24L/12T', 'Courses may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO353H1', 'Special Topics in Economics with Data Analytics', '24L/12T', 'Seminars or workshops in economics with a data analytics component may be offered in one or more topics each year. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO354H1', 'Special Topics in Economics with Data Analytics', '24L/12T', 'Seminars or workshops in economics with a data analytics component may be offered in one or more topics each year. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO356H1', 'Special Topics in Financial Economics', '24L/12T', 'Courses may be offered in one or more subjects each year. Students must meet the prerequisites announced by the Department.', null, 3, null::jsonb),
    ('ECO358H1', 'Financial Economics I', '24L/12T', 'An introduction to economics of financial assets and financial markets. Topics: inter-temporal choice, expected utility theory, security valuation, selected asset pricing models, market efficiency, and the term structure of interest rates - essential materials for an understanding of the role and operation of financial markets.', 'ACT349H1,  ECO358H5,  MGT231H5,  RSM332H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO359H1', 'Financial Economics II: Corporate Finance', '24L/12T', 'Agency and incomplete information problems inherent in financial transactions; the role of contractual arrangements in overcoming them. Financial constraints on investment decisions of firms; the financial system in economic growth; the legal system in the functioning of financial markets. A look at theoretical and empirical literature covering these issues.', 'ACT349H1,  ECO359H5,  MGT232H5,  RSM333H1', 3, '{"operator": "AND", "items": ["ECO358H1"]}'::jsonb),
    ('ECO362H1', 'Economic Growth', '24L/12T', 'The course considers a broad range of issues that underlie economic growth, including technical progress and the accumulation of human and physical capital. Beyond these factors, the course also investigates the efficiency with which capital is used, the role of foreign trade, and the possible roles of institutions and geography.', 'ECO362H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO364H1', 'International Trade Theory', '24L/12T', 'An examination of the causes and consequences of international trade. The first half develops traditional models of comparative advantage. The second half examines more recent theoretical and empirical work on trade & wages, the political economy of trade, outsourcing, and firm heterogeneity.', 'ECO230Y1,  ECO231H1,  ECO364H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO365H1', 'International Monetary Economics', '24L/12T', 'Introduction to open economy macroeconomics and international finance. The core objective of the course is to develop macroeconomic models of open economies that can be applied towards gaining an understanding of recent events such as US deficits, financial crises, China''s exchange rate policy and the Euro.', 'ECO230Y1,  ECO232H1,  ECO365H5', 3, '{"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}'::jsonb),
    ('ECO367H1', 'The Economics of Inequality', '24L/12T', 'This course critically analyzes the causes and recent dynamics of economic inequality both between countries as well as within a particular country, with a particular emphasis on the role of public policy. While theoretical models are employed, there is a focus on the critical assessment of empirical evidence. Topics may include the roles of traditional market forces (e.g., globalisation, technological change), institutions (e.g., minimum wage, unions) as well as race and gender. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO368H1', 'Economics of Conflict', '24L/12T', 'This course explores the links between violent conflict and socioeconomic development. It focuses on micro-level processes leading to conflict, and how conflict and political violence affect people''s lives at the household and community levels. It also examines how these processes are linked to wider political and economic issues including governance and the role of institutions. Tools from economic theory are applied alongside country-specific and cross-country empirical evidence.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO369H1', 'Health Economics', '24L/12T', 'The provision of health care provides many special problems of informational asymmetry, regulation, insurance and redistribution. A consideration of the demand and supply side problems. Alternative reform proposals for health care are explored.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO372H1', 'Data Analysis and Applied Econometrics in Practice', '24L/12T', 'How multiple regression can be used to answer causal questions. Implications of, and how to interpret different model specifications and identification strategies. Students will read, critically evaluate and replicate existing research, and conduct their own original analyses. Statistical software STATA or R will be used.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO374H1', 'Forecasting and Time Series Econometrics', '24L/12T', 'Introduction to time series econometrics and forecasting. Statistical foundations and economic applications of stochastic processes including ARMA, neural networks with machine learning, VAR, VEC, and volatility models. Students gain practical experience working with economic and financial data, making use of statistical software.', 'STA457H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO375H1', 'Applied Econometrics I', '24L/12T', 'Introduction to econometrics. Statistical foundations and the interpretation of multiple regression models, with an emphasis on cross-sectional data. Application of regressions to a wide variety of economic questions and data sources, including the use of statistical software. Problems in the identification of causality, and an introduction to methods of addressing common statistical issues.', 'ECO375H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO380H1', 'Markets, Competition, and Strategy', '24L/12T', 'This course in applied microeconomics is concerned with the functioning of markets and the behaviour of firms within these markets. The focus is on strategic relationships between organizations, including competitive relationships among firms in the same market and cooperative relationships between a firm and its suppliers and distributors. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', 'ECO312H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO381H1', 'Personnel Economics', '24L/12T', 'An examination of selected material on compensation and incentives in organizations. Topics include: recruitment and hiring, training, turnover, downsizing, motivating workers, teams, allocating authority and task assignment.', 'ECO381H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ECO401H1', 'Topics in Economic Policy', '24L/12T', 'This course covers basic issues in the theoretical and empirical evaluation of public policy. Sample topics include: income redistribution through taxation and the provision of social insurance and public goods, the mitigation of externalities, and welfare analysis in behavioural models. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO402H1', 'Topics in Health Economics', '24L/12T', 'This course explores a variety of topics in health economics, providing students with an overview of current and historical institutional characteristics of the market for, and public policy towards, health care. Students will apply theoretical and empirical tools to current domestic and international issues in health policy. No previous background in health economics is required.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO403H1', 'Topics in Development Economics and Policy', '24L/12T', 'This course covers a variety of topics pertaining to economic development and associated policies. Depending on the course instructor, the focus may be on theories and policies related to poverty alleviation, human capital formation, financial markets, international trade, governance or economic growth. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO404H1', 'Topics in Managerial Economics', '24L/12T', 'Applies quantitative economic methods to real world business-oriented cases. Sample topics include: new product design, decision making under uncertainty, market segmentation and price discrimination, inventory analysis, game theoretic analysis of price wars, financial portfolio design, and optimal pricing. Involves substantial modeling in Excel, regression analysis, optimization methods, and financial reports. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO406H1', 'Developmental Macroeconomics', '24L/12T', 'This course studies a growth model applicable to both middle-income developing countries and resource-rich developed countries. Special attention is paid to causes of cyclical currency overvaluation, particularly Dutch disease and excessive capital inflows.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO407H1', 'Competing Views in Macroeconomic Theory and Policy', '24L/24T', 'Provides students with a systematic analysis of competing perspectives on key areas of macroeconomic theory and policy. Special attention paid to competing views regarding key fiscal, monetary, and trade policy issues as applied to Canada.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO409H1', 'Topics in Money, Banking, and Finance', '24L/12T', 'This course examines the foundations of money and financial institutions using tools mastered in micro and macroeconomics. The goal is a set of principles valid for the analysis of monetary policy and institutional regulation in a variety of real world settings.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO410H1', 'Mergers and Competition Policy', '24L/24T', 'A combined theoretical, empirical and policy approach to mergers amongst competitors (horizontal mergers). Uses microeconomic models including game theory and econometrics. Delves into recent/current matters assessed by antitrust authorities domestically and/or internationally with applications to specific industries.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO372H1", "ECO374H1", "ECO375H1"]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO414H1', 'Energy and Regulation', '24L/12T', 'This course provides a general treatment of the economics of energy markets and the use of regulation in addressing environmental and other issues arising in these markets. A central theme is the search for an appropriate balance between market forces and regulatory/government intervention. Familiarity with tools of microeconomics and statistics/econometrics is essential. Topics include: oil, natural gas, coal and electricity markets, global warming and other externalities, networks, feed-in-tariffs, carbon taxes, ''cap-and-trade'' and incentive regulation.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO417H1', 'Economic Development Policy: Community Engaged Learning', '12L/12T/12P', 'An examination of the causes and consequence of poverty in developing countries with a microeconomic focus, and how it relates it to poverty in the developed world, using a 30-hour service placement at a community organization. Importance of community and context specific factors in policy implementation; learn how local organizations have responded. Use of reflection assignments, papers, group work and class discussions to relate to course concepts. Topics include: poverty traps, health, education, and credit. An application to the instructor is necessary. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO418H1', 'Empirical Applications of Economic Theory', '24L/12T', 'Topics class in applied econometrics, emphasizing empirical industrial organization. Emphasis on a balanced treatment of theory and econometric techniques used in empirical research in industrial organization (the study of firms and markets). How firms behave, how market equilibriums arise and how economic policies are used to affect market equilibriums. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "OR", "items": ["ECO372H1", "ECO374H1", "ECO375H1"]}'::jsonb),
    ('ECO419H1', 'International Macroeconomics', '24L/12T', 'This course studies the causes and consequences of international borrowing and lending and exchange rate fluctuations. We will discuss key empirical facts about these phenomena, develop economic models to understand the forces that drive them, and apply the models to gain insights about a variety of historical contexts like China''s rapid economic development and the recent sovereign debt crises in the Eurozone periphery.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO420Y1', 'Special Topics in Economics', '48S', 'Seminars or workshops may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO421H1', 'Special Topics in Economics', '36S', 'Seminars or workshops may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO422H1', 'Special Topics in Economics', '36S', 'Seminars or workshops may be offered in one or more subjects each year.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO424H1', 'Topics in Experimental Economics', '24L/12T', 'Experimental Economics is a relatively new and very exciting field in economics. While most data used in economics is observational, experimentalists use controlled environments to study various economic issues: from individual decision making, to interaction in games and markets, to asset markets and even macroeconomic issues. In this “hands on” course, students read the background literature in a few areas of current academic research, design and conduct human-subject experiments, ultimately submitting a paper where they draw conclusion from their analysis of real data.', 'ECO421H1 (Special Topics in Economics: Experimental Economics), taken Fall 2020 and Fall 2022.', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO425H1', 'Business Cycles', '24L/12T', 'This course builds on material covered in  ECO208Y1. Students will learn how to use business cycle models to better understand key empirical features of the macroeconomy. Topics covered include: the financial crisis, monetary policy, fiscal policy, theories of unemployment, and the effects of innovation on economic fluctuations, the Great Depression and the Financial Crisis.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO426H1', 'Market Design', '24L/12T', 'This course presents the theory and practice of market design, including matching markets and auctions. Sample topics include: school choice, kidney exchange, spectrum auctions, and keyword auctions.', null, 3, '{"operator": "OR", "items": ["ECO316H1", "ECO326H1"]}'::jsonb),
    ('ECO427H1', 'Economics of Information', '24L/12T', 'This course examines the role and the use of information in strategic situations. The class will expand on the material covered in game theory classes and illustrate it with applications. Topics include: communication, signalling, building reputations, adverse selection, etc.', 'ECO421H1 (Special Topics in Economics: Economics of Information), offered in Winter 2018 and Winter 2020.', 3, '{"operator": "OR", "items": ["ECO316H1", "ECO326H1"]}'::jsonb),
    ('ECO428H1', 'Classical Economic Thought', '24L/12T', 'An examination of the price, distribution, and growth theories of major economic thinkers before 1870, from pre-classical contributions by Aristotle, Mercantilists, and Physiocrats to the classical authors Adam Smith, David Ricardo, T.R. Malthus, and Karl Marx.', 'ECO322Y5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}]}'::jsonb),
    ('ECO429H1', 'Economic Thought after 1870', '24L/12T', 'Economic analysis between 1870 and 1960, from the foundations of microeconomics by the Marginal Utility theorists of the 1870s (Jevons, Menger, and Walras), Alfred Marshall in the 1890s, and the capital theorists Bohm-Bawerk and Fisher in the early 1900s, to the Keynesian revolution in macroeconomics in the 1930s and Friedman''s counter-revolution in the 1950s.', 'ECO322Y5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}]}'::jsonb),
    ('ECO430Y1', 'Reading Course or Thesis', null, 'Intended for advanced Specialist students who have exhausted course offerings in a particular area. Students may apply by submitting an application detailing their proposed topic, consult Timetable for more information. The course is open only when a faculty member is available and willing to supervise. Applications will be jointly reviewed by the faculty member and Associate Chair, Undergraduate Studies. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO431H1', 'Reading Course or Thesis', null, 'Intended for advanced Specialist students who have exhausted course offerings in a particular area. Students may apply by submitting an application detailing their proposed topic, consult Timetable for more information. The course is open only when a faculty member is available and willing to supervise. Applications will be jointly reviewed by the faculty member and Associate Chair, Undergraduate Studies. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO434H1', 'Topics in Political Economy', '24L/12T', 'This course surveys recent advances in political economy, emphasizing the critical evaluation of empirical evidence pertaining to political economic theories. Topics vary by year, but may include: voters and electoral competition, and the political economy of media and political agency.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO316H1", "ECO326H1"]}, {"operator": "OR", "items": ["ECO374H1", "ECO375H1"]}]}'::jsonb),
    ('ECO435H1', 'The Economics of Modern China', '24L/12T', 'A focus on post-1949 Chinese economy, and the PRCs economic legacy. Economic development during the Maoist period, particularly post-1979 reforms. China''s experience is compared to Eastern Europe''s and the role of China in the rapidly growing East Asian economy. This is a limited enrolment seminar requiring extensive reading.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}]}'::jsonb),
    ('ECO437H1', 'Quantitative Macroeconomics', '24L/12T', 'In order to capture the complexity of economic behaviour and interactions, especially with a significant time dimension, modern models of the macroeconomy make considerable use of computer simulation. This course teaches students both how to develop the economic models, and how to solve and work with them computationally.', null, 3, '{"operator": "AND", "items": ["ECO325H1"]}'::jsonb),
    ('ECO438H1', 'Topics in Behavioural Economics', '24L/12T', 'Behavioural Economics is a relatively new field that incorporates insights gained from psychological, experimental and neuroscientific studies. Research methods adapted from behavioural economics are now being employed in virtually every field in economics. The course will cover the main themes in behavioural economics: individual choices under risk and uncertainty, reference-dependent choices, intertemporal preferences, other-regarding preferences, bounded rationality in individual and interactive decision-making, and the measurement of rationality and recovery of preferences.', 'ECO422H1 (Special Topics in Economics: Topics in Behavioural Economics), offered in Winter 2018, Winter 2019, and Winter 2020.', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO439H1', 'Empirical Methods in Microeconomics', '24L/12T', 'This course studies the methods used in modern program evaluation and micro-econometrics to identify causal effects in the presence of potentially unobserved confounding factors. Covers a range of methods and designs, both experimental and quasi-experimental. There is a heavy emphasis on the application of these methods to a broad range of economic questions. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "OR", "items": ["ECO372H1", "ECO374H1", "ECO375H1", {"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1"]}]}]}'::jsonb),
    ('ECO446H1', 'Advanced Public Economics', '24L/12T', 'Advanced topics in public economics and economic analysis of Canadian public policy. Through a mix of lectures and independent research, students will acquire theoretical and empirical tools for public policy analysis. Topics may include: income inequality and redistribution; fiscal federalism; taxation of corporate profits; and policies to deal with public goods and externalities. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', 'ECO336Y1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO451H1', 'Macroeconomic Growth', '24L/12T', 'Studies current empirical evidence, and corresponding theoretical models to explain and understand macroeconomic growth, and its varied experience across countries. Coverage and depth of treatment go beyond  ECO362H1. Students may benefit from, but need not have taken  ECO362H1.', null, 3, '{"operator": "AND", "items": ["ECO325H1"]}'::jsonb),
    ('ECO456H1', 'Special Topics in Financial Economics', '24L/12T', 'Courses may be offered in one or more subjects each year. Students must meet the prerequisites announced by the Department.', null, 3, null::jsonb),
    ('ECO459H1', 'International Trade Regulation', '24L', 'The theory and political economy of international trade, with examination of specific trade institutions: Bretton Woods, WTO, NAFTA, tariff administration, most-favoured nation treatment, antidumping regulation, subsidies and countervailing duties, agriculture, trade in services, trade-related intellectual property, trade and environment, trade and developing countries.', null, 3, '{"operator": "AND", "items": ["ECO364H1", "ECO365H1"]}'::jsonb),
    ('ECO461H1', 'The Economics of Financial Risk Management', '24L/12T', 'This course is intended primarily for students in the Financial Economics specialist program and is not open to students in the BCom program. The role of risk management in both private and public sectors, a discussion of why firms and government should hedge financial risks; individual and social gains of financial risk management; identification and quantification of financial risks (including Value-at-Risk measures); how derivative securities can be used for financial risk management.', 'ACT349H1,  RSM435H1, ECO460H5, ECO461H5', 3, '{"operator": "AND", "items": ["ECO358H1"]}'::jsonb),
    ('ECO462H1', 'Financial Econometrics', '24L/12T', 'This course is intended primarily for students in the Financial Economics specialist program. An introduction to the econometrics used in empirical finance, with an emphasis on estimation and inference using computer based applications. Topics will include: parametric and nonparametric models of volatility, evaluation of asset pricing theories, and models for risk management and transactions data.', null, 3, '{"operator": "AND", "items": ["ECO358H1", {"operator": "OR", "items": ["ECO375H1", "ECO375H5"]}]}'::jsonb),
    ('ECO464H1', 'Empirical Financial Economics', '24L/12T', 'The course develops the tools used in empirical research in financial economics. Coverage may include: discrete choice models, duration models, instrumental variables, differences-in-differences, regression discontinuity, propensity score estimators, sample selection models and cumulative abnormal return calculation. Topics are drawn from: ownership structure, mergers and acquisitions, capital structure, payout policy, CEOs'' effect on the firm, executive compensation, insider trading, shareholder activism, and bank financing. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO358H1", "RSM332H1"]}, {"operator": "OR", "items": ["ECO374H1", "ECO375H1", "ECO375H5", "ECO327Y5"]}]}'::jsonb),
    ('ECO465H1', 'International Finance', '24L/12T', 'An advanced course that addresses topics in international finance and macroeconomics. Potential topics include: foreign exchange market; exchange rate determination; empirical models of exchange rates; international financial markets and uncertainty; international CAPM and home bias; sovereign debt; optimal capital controls.', null, 3, '{"operator": "OR", "items": ["ECO365H1", {"operator": "AND", "items": ["ECO325H1", "ECO374H1"]}, {"operator": "AND", "items": ["ECO325H1", "ECO375H1"]}]}'::jsonb),
    ('ECO466H1', 'Empirical Macroeconomics and Policy', '24L/12T', 'Building on  ECO325H1,  ECO374H1 and  ECO375H1, students increase their data literacy and learn modelling techniques to address policy issues. The course covers monetary policy conduct, central bank use of general equilibrium models, and basic techniques for predicting key macroeconomic variables. The class is divided into groups making regular presentations on current global and domestic issues, the economic outlook, and how the Bank of Canada should adjust monetary policy in the short run. At the end of the course, traditionally a group is chosen to compete in the Bank of Canada Governor''s Challenge. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', 'ECO466H5', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO208Y1", "ECO209Y1", "ECO202Y1", "ECO325H1"]}, {"operator": "OR", "items": ["ECO374H1", "ECO375H1"]}]}'::jsonb),
    ('ECO475H1', 'Applied Econometrics II', '24L/12T', 'A research-oriented course continuing from ECO375H. The regression model is extended in several possible directions: time series analysis; panel data techniques; instrumental variables; simultaneous equations; limited dependent variables. Students will complete a major empirical term paper, applying the tools of econometrics to a topic chosen by the student.', 'ECO475H5', 3, '{"operator": "OR", "items": ["ECO375H1", "ECO374H1"]}'::jsonb),
    ('ECO480H1', 'Special Topics in Economics with Data Analytics', '24L/12T', 'Seminars or workshops in economics with a data analytics component may be offered in one or more topics each year. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO481H1', 'Special Topics in Economics with Data Analytics', '24L/12T', 'Seminars or workshops in economics with a data analytics component may be offered in one or more topics each year. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites and necessary support for applicable software is provided.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO482H1', 'Machine Learning Applications in Macroeconomic Finance', '24L/12T', 'This course introduces students to machine learning concepts and techniques, focusing on applications in macroeconomic finance. In the first part we review supervised and unsupervised machine-learning methods. In the second part, we focus on various questions and topics in macro-finance where the use of machine learning is increasingly common. Hands-on use of these techniques to solve economic problems in macro-finance will prepare students for more advanced machine learning courses.', 'CSC311H1,  STA314H1,  ECO481H1 (Special Topics in Economics with Data Analytics: Macroeconomic Finance with Machine Learning Applications) taken in Fall 2022 or Winter 2023.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC148H1"]}, {"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO483H1', 'Health and Economic Inequality', '24L/12T', 'This course provides an interactive overview of the key themes in health and economic inequality, paying particular attention to the bidirectional causal relationship: poor health can lead to poor economic outcomes, while economic insecurity can have serious health implications. Focusing on the current empirical literature and employing a hands-on approach to economic and health data, we investigate social and economic determinants such as income, geography, family, health care, race and gender. Note: hands-on analysis of real-world data using computer programs is a course requirement. The course is open to all students who meet the prerequisites, and necessary support for applicable software is provided.', 'ECO481H1 (Special Topics in Economics with Data Analytics: Health and Economic Inequality) taken in Fall 2023.', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"credits": 1.0, "department": "ECO"}]}'::jsonb),
    ('ECO499H1', 'Honours Essay in Applied Microeconomics', '24L/12T', 'Students will complete an original research paper on a topic of their choosing. Topic must be microeconomic and applied, meaning all papers will involve data and quantitative (regression) analysis.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1"]}, {"operator": "OR", "items": ["ECO202Y1", "ECO208Y1", "ECO209Y1"]}, {"operator": "OR", "items": ["ECO220Y1", "ECO227Y1", {"operator": "AND", "items": ["STA237H1", "STA238H1"]}, {"operator": "AND", "items": ["STA247H1", "STA248H1"]}, {"operator": "AND", "items": ["STA257H1", "STA261H1"]}]}, {"operator": "OR", "items": ["ECO372H1", "ECO374H1", "ECO375H1"]}]}'::jsonb),
    ('EDS260H1', 'Equity and Diversity in Education', '24L', 'This course focuses on raising awareness and sensitivity to equity and diversity issues facing teachers and students in diverse schools and cultural communities. It builds knowledge of how oppression works and how cultural resources and educational practices may be brought to bear on reducing oppression and improving equity. Restricted to students enrolled in the Education and Society Minor.', 'VIC260H1,  JSV202H1', 3, null::jsonb),
    ('EDS261H1', 'Child and Adolescent Development in Education', '36L', 'This course examines how children and adolescents develop and explores how best to facilitate their growth and learning in the area of education. Major topics include cognitive, emotional, social, moral, physical and language development. Themes addressed include interpersonal relationships such as pro-social and aggressive behaviour, as well as the influence of schooling, family life and culture. Restricted to students enrolled in the Education and Society Minor.', 'VIC261H1,  JSV201H1', 2, null::jsonb),
    ('EDS262H1', 'Communication and Conflict Resolution in Education', '36L', 'This course aims to develop an understanding of social conflict and cultural diversity. How does conflict act as a catalyst for change? What do socio-cultural, cognitive, and motivational approaches teach us about conflict? Topics include: effects of conflict, human rights principles, cross-cultural understanding. Restricted to students enrolled in the Education and Society Minor.', 'VIC262H1,  JSV200H1', 3, null::jsonb),
    ('EDS263H1', 'Disability, Inclusion and Education', '24L', 'This course explores the historical and contemporary ways in which societies define and respond to individuals with a broad range of needs, abilities and disabilities, as it intersects with educational access and practice. Through an examination of diverse knowledge sources such as children''s books, poetry, videos, social media, policy documents and academic research, students will learn about the lived experiences of exceptional learners, while promoting understanding, compassion, and pathways for change. Students will also be challenged to examine their own beliefs and practices to ensure they have the knowledge, dispositions, and confidence necessary to promote the success and inclusion of individuals with special education needs in a wide variety of settings. Strategies for adapting curriculum and the learning environment to promote the inclusion of individuals with specific disabilities are discussed. Restricted to students enrolled in the Education and Society Minor.', null, 3, null::jsonb),
    ('EDS265H1', 'Introduction to Teaching', '36S', 'Builds understanding of teaching as professional practice. The course primarily focuses on the research base underlying policies and documents such as the Foundations of Professional Practice. This course is restricted to students enrolled in the Education and Society Minor.', 'VIC265H1,  VIC362H1', 3, null::jsonb),
    ('EDS355H1', 'Social Justice in Education', '36S', 'This course enables students to develop an understanding of historical and contemporary issues relating to social justice in education. The course builds an anti-oppressive praxis for working in diverse educational contexts, from classrooms and schools to state institutions and non-governmental organizations. The course approaches oppression as an outcome of interrelated structures co-constructed by race, ethnicity, disability, gender, sexuality, class, nationality, and age, focusing on the ways in which these intersect and influence one another. Students will develop and apply research skills in the design and implementation of a social action initiative relating to an equity, diversity, or social justice issue.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('EDS356H1', 'Multiliteracies in Education', '36L', 'This course introduces students to a multiliteracies framework through the pedagogical lens of social justice and diversity. Class participants learn to integrate the multimodalities of literacy in their teaching practice and expand their understanding of 21st-century literacy. Themes include language development, print literacy, digital literacy, critical literacy, visual literacy and multicultural perspectives on literacy.', null, 3, null::jsonb),
    ('EDS357H1', 'Education in a Global Context', '24L', 'This course provides a historical overview and contemporary analysis of perspectives and practices of international education with a focus on international development and policy. Factors that shape the global architecture of education will be explored; these may include theories of globalization, education reform, comparative education, peace education, international schooling and global citizenship education. Students will have the opportunity to analyze education reforms and to address issues related to access and quality of learning. Restricted to students enrolled in the Education and Society Minor.', null, 3, null::jsonb),
    ('EDS358H1', 'Residential Schools and Education in Canada', '24S', 'An exploration of Residential Schools in Canada and their impacts on education and lives of First Nations, Métis and Inuit peoples. This course investigates the historical educational ideology of residential schools and their relationship to colonization, the role of government and organized religion in the residential school system, and contemporary strategies that encourage stable and trusting relationships with Indigenous communities. This course will also explore aspects of the Final Report of the Truth and Reconciliation Commission Calls to Action.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('EDS360H0', 'Education Internship - International', null, 'Students are required to complete an internship in an educational environment in an international or out-of-province context. Arranged through Victoria College and the Centre for International Exchange, the International/Out-of-province Internship is only for students in the Education & Society Minor. Written assessment of the internship is required. Restricted to students enrolled in the Education and Society Minor. Not eligible for CR/NCR option.', 'EDS360H1,  EDS360Y1,  EDS360Y0', 3, null::jsonb),
    ('EDS360H1', 'Education Internship', null, 'Students are required to complete an internship in an educational environment. This can be satisfied by participation in an organization with the approval of the Program Coordinator. Written assessment of the internship is required. Restricted to students enrolled in the Education and Society Minor. Not eligible for CR/NCR option.', 'EDS360Y1', 3, null::jsonb),
    ('EDS360Y0', 'Education Internship - International', null, 'Students are required to complete an internship in an educational environment in an international or out-of-province context. Arranged through Victoria College, the International/Out-of-province Internship is only for students in the Education & Society Minor. Written assessment of the internship is required. Restricted to students enrolled in the Education and Society Minor. Not eligible for CR/NCR option.', 'EDS360H1,  EDS360Y1', 3, null::jsonb),
    ('EDS360Y1', 'Education Internship', null, 'Students are required to complete an internship in an educational environment. This can be satisfied by participation in an organization with the approval of the Program Coordinator. Written assessment of the internship is required. Restricted to students enrolled in the Education and Society Minor. Not eligible for CR/NCR option.', 'EDS360H1,  EDS360Y0', 3, null::jsonb),
    ('EDS363H1', 'Teaching Math: The JUMP Approach', '24S', 'This course will challenge the widely accepted idea that people need to be born with a special gift or natural ability to excel in mathematics. New research in education and cognitive science suggests that young learners often struggle in school because they are not taught in a way that allows their brains to work efficiently. This course will examine barriers that prevent students from learning and methods of teaching that can help all students reach their full potential (not only in math). Math lovers and math phobic students are welcome: the course aims to help students develop deeper levels of confidence and understanding in mathematics so they can become effective teachers themselves.', 'VIC363H1', 3, null::jsonb),
    ('EDS368H1', 'Special Topics in Education and Society', '24L', 'In-depth study of a topic related to education and society. Content varies with instructor. Please see Victoria College website for current offerings: https://vic.utoronto.ca/academic-programs/special-topics-courses/eds368h.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('EDS369H1', 'Special Topics in Education and Society', '24L', 'In-depth study of a topic related to education and society. Content varies with instructor. Please see Victoria College website for current offerings:  https://vic.utoronto.ca/academic-programs/special-topics-courses/eds369h.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('EEB125H1', 'Introductory Computation and Data Science for the Life and Physical Sciences', '24L/12T', 'Life and physical scientists increasingly use big and complex datasets to answer questions about society and the natural world. In this course, students will develop introductory programming knowledge and data acumen to explore topics drawn from biology, chemistry, physics, and psychology. Students will learn to create and run computer programs, organize ideas using data to communicate clearly to others, break a complex problem into simpler parts, apply general data science principles to specific cases, distinguish causation from correlation and coincidence, and negotiate tradeoffs between different computational and statistical approaches.', 'CSC111H1,  CSC148H1,  STA130H1,  STA238H1,  STA248H1,  STA261H1,  GGR274H1', 5, null::jsonb),
    ('EEB196H1', 'Using Ecology and Evolution to Understand our World', '24L', 'Understand the living world by learning principles of ecology and evolution. Through discussion, scientific literature research, seminal readings, written reports and presentations, you will discover how scientists ask and answer questions in ecology and evolution. Specific topics will vary to emphasize the expertise of the instructor, with examples including: Are humans still evolving? What is causing the sixth extinction crisis and how can we protect endangered species? Are species shifting their ranges to mitigate the impacts of climate change, and should we be helping them? How do diseases evolve and can we use evolutionary tools to control diseases of concern? Why are there so many species, and do introduced species increase or lower this diversity? Can and should we use evolution to create improved species? For non-science students in all disciplines. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('EEB197H1', 'Biodiversity and the City', '24L', 'Most of us are urban creatures, but we as people are not the only urban creatures. In this seminar we will explore the diversity of animal and plant species comprising the ecological community that we call “Toronto”. We will learn their names, whether they are endemic (from here originally) or newcomers, general aspects of their biology that suit them to living in an urban environment, how natural selection shapes the traits similarly and differently for species in urban versus wilderness settings, and what happens when the wild and the domesticated members of the community meet one another. For non-science students in all disciplines. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('EEB198H1', 'Genes and Behaviour', '24L', 'In this course you will experience the new paradigm in behaviour genetic research. You will learn why the concept of a nature-nurture dichotomy is passé and that it has been replaced by a new understanding gained from animal and human research in the areas of gene by environment interaction and epigenetics. We will discuss how our genome listens to our environment and the effect this has on our health and behaviour. We will learn why our early experiences are critical for the development of our brains and our bodies. Together this new body of knowledge will help us understand how individual differences in behaviour and health arise. For non-science students in all disciplines. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('EEB199H1', 'Humans, Evolution and Ecology', '24L', 'Learn about the evolution and ecology of humans and other species. Through discussion, scientific literature research, seminal readings, written reports and presentations you will discover scientific answers to questions such as (topics vary among years): How did life originate? Why are there so many species? Where did humans come from? Will humans become extinct? How can we explain human DNA and human brain size? Need we worry about climate change? What is causing the sixth extinction crisis? Are there ecological limits to human population size? What will life be like in the Anthropocene? Are humans still evolving? For non-science students in all disciplines. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('EEB202H1', 'Plants and Society', '24L', 'The importance of plants to society. Topics include: plant biology, domestication of crop plants, plant breeding and genetic engineering, biological invasions, conservation, biodiversity and genetic resources, ecological implications of advances in modern plant science, macroevolution of plants, forest utilization. For non-science students in all years and disciplines.', 'BIO120H1', 4, null::jsonb),
    ('EEB208H1', 'Ecosystems and the Human Footprint', '24L/12T', 'An introduction to the diversity of Earth''s aquatic and terrestrial ecosystems (e.g., coral reefs, lakes, tropical rainforests); the history of industrialization and human population growth; how the human footprint impacts ecosystems (e.g., ecosystem function, biological diversity); and strategies to maintain, recover and restore ecosystems. This is a course for non-science students in all years and disciplines.', 'BIO120H1,  ENV200H1,  ESS205H1', 4, null::jsonb),
    ('EEB214H1', 'Evolution and Adaptation', '24L/12T', 'Evolution and adaptation of life on Earth. Introduction to the theory of evolution by natural selection. Topics may include evidence supporting the fact of evolution, and how evolutionary theory can help explain the world around us, such as how species are formed, and the evolution of sex, infanticide, and disease. For non-science students in all years and disciplines.', 'BIO120H1', 4, null::jsonb),
    ('EEB215H1', 'Conservation Biology', '24L/12T', 'Introduction to the scientific discipline that deals with threatened species and habitats. Topics include biodiversity, extinction, threats, demography, genetic diversity, protecting, managing and restoring ecosystems (e.g., nature reserves, captive breeding, conservation corridors), sustainable development, and global warming. Ties between the study of conservation biology and environmental law, economics, and policy will also be covered. This is a course for non-science students in all years and disciplines.', 'BIO120H1', 4, null::jsonb),
    ('EEB225H1', 'Biostatistics for Biological Sciences', '36L/12P', 'A statistics course designed especially for life science students, using examples from ecology and evolution where appropriate. Students learn to choose and use statistics that are appropriate to address relevant biological questions and hypotheses. Lectures and computer labs will be used to cover the following methods: sampling and experimental design, data exploration, correlation, regression, ANOVA, Chi-square, and other parametric tests.', 'ECO220Y1/  ECO227Y1/  GGR270H1/  HMB325H1/  PCL376H1/  PSY201H1/  SOC300Y1/  STA220H1/  STA288H1', null, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB240H1', 'Environmental Biology: From Organisms to Ecosystems', '24L/15P', 'Biological processes depend on, and impact, environmental conditions that change across space and time, from local scales to biomes, and from seconds to millennia. This course examines the relationships among organisms, populations, and communities, and ecosystems, including the increasing impacts of human activity on environmental conditions. It draws links between global change, biological diversity, and the functions of ecosystems from local to global scales. We use examples from both aquatic and terrestrial ecosystems and emphasize the connectivity across ecosystems and ecosystem-types. Field trips and labs. Mandatory day-long field trip on a weekend. (Lab Materials Fee: $26).', 'ENV234H1', 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB255H1', 'Essentials of Biodiversity Science and Conservation Biology', '24L/24T', '“Classical” and “new” concepts in biodiversity and conservation. Topics may include: evolution and ecology in the past (Holocene) and future (Anthropocene); levels and kinds of biodiversity; valuing biodiversity through ecological economics; causes of endangerment; predicting extinction; genetic and demographic theory; habitat protection and captive breeding; conservation policies and endangered species acts; designing future biodiversity.', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB263H1', 'Comparative Vertebrate Anatomy', '24L/36P', 'The ontogeny and phylogeny of vertebrate structure are considered within the context of evolutionary theory. Functional aspects of the various organ systems are examined. Representative vertebrates are analyzed (with brief dissection of some forms) in laboratory to illustrate selected anatomical features and to provide practical exposure to vertebrate construction. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB266H1', 'Animal Diversity: Invertebrates', '24L/18P', 'The diversity of invertebrates (e.g. sponges, jellyfish, flatworms, molluscs, segmented worms, round worms, arthropods, echinoderms and several smaller phyla) is explored, focusing on taxonomic characters that define each group and their placement in the evolutionary tree of life, ecological function, biological requirements, and geographical distribution. Labs emphasize identification and recognition of major groups, including dissection when appropriate. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB267H1', 'Animal Diversity: Vertebrates', '24L/18P', 'Introduction to the diversity of chordate animals (vertebrates, tunicates, and lancelets), focusing on morphological, physiological, ecological and behavioural traits that make each group special and how those traits increase vulnerability to human-based exploitation. Labs involve living organisms whenever possible, but only for display purposes.', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB268H1', 'Plant and Microbial Diversity', '24L/36P', 'Introduction to the biology of algae, fungi, and land plants. Lectures and labs emphasize the diversity of organisms with a focus on life cycles, ecology, and evolution. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('EEB299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EEB299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EEB313H1', 'Quantitative Methods in R for Biology', '24L/24P', 'The quantitative analysis and management of biological data is crucial in modern life sciences disciplines. Students will develop skills with R as applied to problems in ecology and evolutionary biology to learn reproducible approaches for data management, data manipulation, visualization, modelling, statistical analysis, and simulation for solving biological problems.', 'STA130H1,  PSY305H1', 5, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "STA288H1", "STA220H1"]}]}'::jsonb),
    ('EEB314H1', 'Modeling in Ecology and Evolution', '24L/12P', 'Mathematics is central to science because it provides a rigorous way to go from a set of assumptions to their logical consequences. In ecology & evolution this might be how we think a virus will spread and evolve, how climate change will impact a threatened population, or how much genetic diversity we expect to see in a randomly mating population. In this course you''ll learn how to build, analyze, and interpret mathematical models of increasing complexity through readings, lectures, homework, computer labs, and a final project.', 'EEB430H1', 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["MAT136H1", "MAT137Y1"]}]}'::jsonb),
    ('EEB318H1', 'Principles of Evolution', '24L/12T', 'Principles and practice of evolutionary biology since Darwin. Topics may include: phylogeny, speciation, mutation and neutral evolution, population genetic variation, quantitative genetics, molecular evolution, natural selection and adaptation, evolutionary conflict and cooperation, and levels of selection.', 'EEB323H1/ EEB324H1', 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB319H1', 'Population Ecology', '24L/36P', 'Abundance and distribution of populations; population growth and regulation; fluctuations, stochasticity and chaos; meta-population persistence and extinction; age and stage-structured populations; interactions within and between species; optimal harvesting; spread of infectious diseases. Labs include experiments and computer simulations. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["EEB225H1", "PSY201H1", "STA220H1", "STA250H1", "STA257H1", "STA288H1", "GGR270H1", "HMB325H1"]}]}'::jsonb),
    ('EEB320H1', 'Dynamics of Ecosystem Processes', '24L/24P', 'This course explores the relationships and feedback between biological communities and the abiotic factors of ecosystems. The course will cover the biogeochemical dynamics of energy and nutrients through ecosystem development and the effects of global change on these processes. The lab component of the course will apply lecture concepts and tools to specific case studies. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB321H1', 'Community Ecology', '24L/36P', 'Nature and analysis of community structure; disturbance and community development; species interactions; community assembly processes. Computer exercises in weekly labs provide training in sampling, simulation, and data analysis.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "PSY201H1", "STA220H1", "STA250H1", "STA257H1", "STA288H1", "GGR270H1", "HMB325H1"]}]}'::jsonb),
    ('EEB322H1', 'Behaviour and Behavioural Ecology', '24L/36P', 'A broad introduction to animal behaviour emphasizing concepts from ethology and behavioural ecology, including foraging, predation, mating systems, parental care and behaviour genetics. Field and laboratory studies are undertaken. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "PSY201H1", "STA220H1", "STA250H1", "STA257H1", "STA288H1", "GGR270H1", "HMB325H1"]}]}'::jsonb),
    ('EEB323H1', 'Evolutionary Genetics', '36L/12T', 'Evolutionary biology rests on a foundation of evolutionary genetics. This course focuses on the core ideas in population genetics and extends to evolutionary genomics. Students are exposed to the mathematical theory underlying evolutionary genetics and will learn the mathematical foundations underlying these ideas. Topics include the population genetics of mutation, migration, drift, and selection, evolutionary analysis of DNA sequences, genome evolution, and the evolution of sexual reproduction.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('EEB324H1', 'Evolutionary Ecology', '36L/12T', 'Empirical and theoretical approaches to key areas of research including natural selection, sexual selection, and life histories. Other topics may include phenotypic plasticity, speciation, co-evolution, and quantitative genetics.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB325H1', 'Evolutionary Medicine', '36L/12T', 'How evolutionary principles can help us better understand health and disease. Concepts from evolutionary biology (e.g., life history theory, coevolution, genomic conflict, constraints and trade-offs) will be applied to key problems in medicine and public health, including antibiotic resistance, aging, cancer, autoimmune disease, and pathogen virulence.', null, 4, '{"operator": "AND", "items": ["BIO130H1", "BIO220H1"]}'::jsonb),
    ('EEB328H1', 'Physiological Ecology', '24L/24T', 'An advanced treatment of the physiological mechanisms controlling plant and animal distribution and ecological success. Topics of focus include photosynthesis and resource balance, water and nutrient relations, temperature effects, and adaptations to abiotic stress.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB340H1', 'Comparative Plant Morphology', '24L/36P', 'This course addresses the origin of land plants and subsequent diversification of land plant vegetative and reproductive form and function. Lectures and laboratory tutorials synthesize morphological and anatomical knowledge from living organisms and fossil records with cellular, physiological and molecular information of land plants and their ancestors throughout geological time. Topics of study include the evolution of (i) vegetative and reproductive meristems, (ii) stem, leaf and root architecture, (iii) vascular tissue, (iv) the ovule habit, and (v) fertilization. (Lab materials fee: $26).', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB362H1', 'Macroevolution', '24L/24T', 'Explores patterns and processes of large-scale evolutionary change, played out over large geographic expanses and extended periods of time. Integrates information from paleontology, phylogenetics, field studies, functional biology, and experiments to link emergent evolutionary patterns to underlying evolutionary processes. Topics include: speciation, phylogenetic inference, adaptive vs. non-adaptive evolution, evolutionary constraints, diversification and extinction, evolutionary innovations, historical biogeography, and the relationship between evolutionary history and ecology. Tutorials will illustrate common analytical approaches to macroevolutionary investigation and provide in-depth exploration of landmark studies in macroevolution.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB365H1', 'Topics in Applied Conservation Biology', '24L/24P', 'Applied conservation biology including management (at the level of species/populations, environments/landscapes, and ecosystems) and how to conserve and maintain biodiversity and ecosystem function (including species and ecosystem distribution modelling).', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "ECO220Y1", "ECO227Y1", "GGR270H1", "HMB325H1", "PSY201H1", "SOC300Y1", "STA220H1", "STA250H1", "STA288H1"]}]}'::jsonb),
    ('EEB380H1', 'Diversity of Insects', '24L/36P', 'Evolutionary history, morphology, physiology, development, behaviour, and ecological significance of insects. Labs focus on identification of major groups of insects found in Ontario and each student makes an insect collection. Insects are collected during field trips during class time and also on Saturday field trips early in the term. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB382H1', 'Diversity of Fishes', '24L/18P', 'Systematics, morphology, ecology, behaviour, biogeography, and conservation of fishes. Identification of major groups of fish; what makes each group biologically special and how those unique traits might contribute to conservation concerns. Labs focus on exercises designed to highlight how ichthyologists actually do research. (Lab Materials Fee: $26)', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB384H1', 'Diversity of Amphibians and Reptiles', '24L/36P', 'Lectures and laboratories examine the natural history, morphology, behaviour, ecology, evolutionary relationships, and biogeography of amphibians (frogs and toads, salamanders, caecilians) and non-avian reptiles (turtles, the tuatara, lizards, snakes, and crocodilians). Students are required to purchase a $25 lab manual.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb)
